def extract_function_info(node):
    """Extract name, signature, parameters, docstring from a function node"""
    func_name = node.name
    params = []
    for arg in node.args.args:
        param_name = arg.arg
        param_type = ast.unparse(arg.annotation) if arg.annotation else 'Any'
        params.append({'name': param_name, 'type': param_type})
    if node.args.vararg:
        params.append({'name': '*' + node.args.vararg.arg, 'type': 'tuple'})
    if node.args.kwarg:
        params.append({'name': '**' + node.args.kwarg.arg, 'type': 'dict'})
    doc = ast.get_docstring(node)
    signature = ast.unparse(node)
    return {'name': func_name, 'signature': signature, 'params': params, 'doc': doc or ''}

def extract_class_info(node):
    """Extract class name, docstring, and its methods"""
    class_name = node.name
    doc = ast.get_docstring(node) or ''
    methods = []
    for n in node.body:
        if isinstance(n, ast.FunctionDef):
            method_info = extract_function_info(n)
            method_info['name'] = f"{class_name}.{method_info['name']}"
            methods.append(method_info)
    return {'name': class_name, 'signature': f'class {class_name}', 'params': [], 'doc': doc, 'methods': methods}

def extract_docs_from_file(file_path):
    docs = []
    try:
        with open(file_path, 'r', encoding='utf-8') as f:
            node = ast.parse(f.read())
        for n in node.body:
            if isinstance(n, ast.FunctionDef):
                docs.append(extract_function_info(n))
            elif isinstance(n, ast.ClassDef):
                class_info = extract_class_info(n)
                docs.append(class_info)
    except Exception as e:
        print(f'Failed to parse {file_path}: {e}')
    return docs

