    c = Circle(fill_opacity=0.7).shift(UL)
    self.add(c)
    shader = Shader(self.renderer.context, source={'vertex_shader': '
                #version 330

                in vec4 in_vert;
                in vec4 in_color;
                out vec4 v_color;
                uniform mat4 u_model_view_matrix;
                uniform mat4 u_projection_matrix;

                void main() {
                    v_color = in_color;
