def process_pullrequests(lst, cur, github_repo, pr_nums):
    lst_commit = github_repo.get_commit(sha=this_repo.git.rev_list('-1', lst))
    lst_date = lst_commit.commit.author.date
    authors = set()
    reviewers = set()
    pr_by_labels = defaultdict(list)
    with concurrent.futures.ThreadPoolExecutor() as executor:
        future_to_num = {executor.submit(github_repo.get_pull, num): num for num in pr_nums}
        for future in tqdm(concurrent.futures.as_completed(future_to_num), 'Processing PRs'):
            pr = future.result()
            authors.add(pr.user)
            reviewers = reviewers.union((rev.user for rev in pr.get_reviews()))
            pr_labels = [label.name for label in pr.labels]
            for label in PR_LABELS:
                if label in pr_labels:
                    pr_by_labels[label].append(pr)
                    break
            else:
                pr_by_labels['unlabeled'].append(pr)
    author_names = []
    for author in authors:
        name = author.name if author.name is not None else author.login
        if name in SILENT_CONTRIBUTORS:
            continue
        if github_repo.get_commits(author=author, until=lst_date).totalCount == 0:
            name += ' +'
        author_names.append(name)
    reviewer_names = []
    for reviewer in reviewers:
        name = reviewer.name if reviewer.name is not None else reviewer.login
        if name in SILENT_CONTRIBUTORS:
            continue
        reviewer_names.append(name)
    for i in pr_by_labels:
        pr_by_labels[i] = sorted(pr_by_labels[i], key=lambda pr: pr.number)
    return {'authors': sorted(author_names), 'reviewers': sorted(reviewer_names), 'PRs': pr_by_labels}

def get_summary(body):
    pattern = '<!--changelog-start-->([^"]*)<!--changelog-end-->'
    try:
        has_changelog_pattern = re.search(pattern, body)
        if has_changelog_pattern:
            return has_changelog_pattern.group()[22:-21].strip()
    except Exception:
        print(f'Error parsing body for changelog: {body}')

def assert_shallow_dict_compare(a: dict, b: dict, message_start: str) -> None:
    """Assert that Directories ``a`` and ``b`` are the same.

    ``b`` is treated as the expected values that ``a`` shall abide by.
    Print helpful error with custom message start.
    """
    mismatch: list[str] = []
    for b_key, b_value in b.items():
        if b_key not in a:
            mismatch.append(f'Missing item {b_key}: {b_value}')
        elif b_value != a[b_key]:
            mismatch.append(f'For {b_key} got {a[b_key]}, expected {b_value}')
    for a_key, a_value in a.items():
        if a_key not in b:
            mismatch.append(f'Extraneous item {a_key}: {a_value}')
    mismatch_str = '\n'.join(mismatch)
    assert len(mismatch) == 0, f'{message_start}\n{mismatch_str}'

