    theme_keys = {'command_help', 'invoked_command', 'heading', 'constraint', 'section_help', 'col1', 'col2', 'epilog'}
    for k, v in parser.items():
        if k in theme_keys and v:
            theme_settings.update({k: Style(v)})
    formatter = {}
    theme = parser['theme'] if parser['theme'] else None
    if theme is None:
        formatter = HelpFormatter.settings(theme=HelpTheme(**theme_settings), **formatter_settings)
    elif theme.lower() == 'dark':
        formatter = HelpFormatter.settings(theme=HelpTheme.dark().with_(**theme_settings), **formatter_settings)
    elif theme.lower() == 'light':
        formatter = HelpFormatter.settings(theme=HelpTheme.light().with_(**theme_settings), **formatter_settings)
    return_val: dict[str, Any] = Context.settings(align_option_groups=parser['align_option_groups'].lower() == 'true', align_sections=parser['align_sections'].lower() == 'true', show_constraints=True, formatter_settings=formatter)
    return return_val

methods.signature:
def format(self, record: logging.LogRecord) -> str:
    """Format the record in a custom JSON format."""
    record_c = copy.deepcopy(record)
    if record_c.args:
        if isinstance(record_c.args, dict):
            for arg in record_c.args:
                record_c.args[arg] = '<>'
        else:
            record_c.args = ('<>',) * len(record_c.args)
    return json.dumps({'levelname': record_c.levelname, 'module': record_c.module, 'message': super().format(record_c)})

