def update_path(self, mob: Mobject, dt: float) -> None:
    new_point = self.traced_point_func()
    if not self.has_points():
        self.start_new_path(new_point)
    self.add_line_to(new_point)
    if self.dissipating_time:
        assert self.time is not None
        self.time += dt
        if self.time - 1 > self.dissipating_time:
            nppcc = self.n_points_per_curve
            self.set_points(self.points[nppcc:])

def __init__(self, *animations: Animation | Iterable[Animation], group: Group | VGroup | OpenGLGroup | OpenGLVGroup | None=None, run_time: float | None=None, rate_func: Callable[[float], float]=linear, lag_ratio: float=0, **kwargs: Any):
    arg_anim = flatten_iterable_parameters(animations)
    self.animations = [prepare_animation(anim) for anim in arg_anim]
    self.rate_func = rate_func
    if group is None:
        mobjects = remove_list_redundancies([anim.mobject for anim in self.animations if not anim.is_introducer()])
        if config['renderer'] == RendererType.OPENGL:
            self.group: Group | VGroup | OpenGLGroup | OpenGLVGroup = OpenGLGroup(*mobjects)
        else:
            self.group = Group(*mobjects)
    else:
        self.group = group
    super().__init__(self.group, rate_func=self.rate_func, lag_ratio=lag_ratio, **kwargs)
    self.run_time: float = self.init_run_time(run_time)

def begin(self) -> None:
    if not self.animations:
        raise ValueError(f'Trying to play {self} without animations, this is not supported. Please add at least one subanimation.')
    self.anim_group_time = 0.0
    if self.suspend_mobject_updating:
        self.group.suspend_updating()
    for anim in self.animations:
        anim.begin()

