        return vmobject.get_stroke_color()
    return vmobject.get_color()

def interpolate_submobject(self, submobject: Mobject, starting_submobject: Mobject, outline, alpha: float) -> None:
    index: int
    subalpha: float
    index, subalpha = integer_interpolate(0, 2, alpha)
    if index == 0:
        submobject.pointwise_become_partial(outline, 0, subalpha)
        submobject.match_style(outline)
    else:
        submobject.interpolate(outline, starting_submobject, subalpha)

def _set_default_config_from_length(self, vmobject: VMobject | OpenGLVMobject, run_time: float | None, lag_ratio: float | None) -> tuple[float, float]:
    length = len(vmobject.family_members_with_points())
    if run_time is None:
        run_time = 1 if length < 15 else 2
    if lag_ratio is None:
        lag_ratio = min(4.0 / max(1.0, length), 0.2)
    return (run_time, lag_ratio)

