def __init__(self, mobject: Mobject, shape: type[Rectangle] | type[Circle]=Rectangle, fade_in: bool=False, fade_out: bool=False, time_width: float=0.3, buff: float=SMALL_BUFF, color: ParsableManimColor=YELLOW, run_time: float=1, stroke_width: float=DEFAULT_STROKE_WIDTH, **kwargs: Any):
    if shape is Rectangle:
        frame: SurroundingRectangle | Circle = SurroundingRectangle(mobject, color=color, buff=buff, stroke_width=stroke_width)
    elif shape is Circle:
        frame = Circle(color=color, stroke_width=stroke_width).surround(mobject, buffer_factor=1)
        radius = frame.width / 2
        frame.scale((radius + buff) / radius)
    else:
        raise ValueError('shape should be either Rectangle or Circle.')
    if fade_in and fade_out:
        super().__init__(FadeIn(frame, run_time=run_time / 2), FadeOut(frame, run_time=run_time / 2), **kwargs)
    elif fade_in:
        frame.reverse_direction()
        super().__init__(FadeIn(frame, run_time=run_time / 2), Uncreate(frame, run_time=run_time / 2), **kwargs)
    elif fade_out:
        super().__init__(Create(frame, run_time=run_time / 2), FadeOut(frame, run_time=run_time / 2), **kwargs)
    else:
        super().__init__(ShowPassingFlash(frame, time_width, run_time=run_time), **kwargs)

def __init__(self, mobject: Mobject, time_on: float=0.5, time_off: float=0.5, blinks: int=1, hide_at_end: bool=False, **kwargs: Any):
    animations = [UpdateFromFunc(mobject, update_function=lambda mob: mob.set_opacity(1.0), run_time=time_on), UpdateFromFunc(mobject, update_function=lambda mob: mob.set_opacity(0.0), run_time=time_off)] * blinks
    if not hide_at_end:
        animations.append(UpdateFromFunc(mobject, update_function=lambda mob: mob.set_opacity(1.0), run_time=time_on))
    super().__init__(*animations, **kwargs)

def __init__(self, homotopy: Callable[[float, float, float, float], tuple[float, float, float]], mobject: Mobject, run_time: float=3, apply_function_kwargs: dict[str, Any] | None=None, **kwargs: Any):
    self.homotopy = homotopy
    self.apply_function_kwargs = apply_function_kwargs if apply_function_kwargs is not None else {}
