        shaded_rgbas[0, :3] = get_shaded_rgb(shaded_rgbas[0, :3], get_3d_vmob_start_corner(vmobject), get_3d_vmob_start_corner_unit_normal(vmobject), light_source_point)
        shaded_rgbas[1, :3] = get_shaded_rgb(shaded_rgbas[1, :3], get_3d_vmob_end_corner(vmobject), get_3d_vmob_end_corner_unit_normal(vmobject), light_source_point)
