def _partite_layout(nx_graph: NxGraph, scale: float=2, partitions: Sequence[Sequence[Hashable]] | None=None, **kwargs: Any) -> dict[Hashable, Point3D]:
    if partitions is None or len(partitions) == 0:
        raise ValueError('The partite layout requires partitions parameter to contain the partition of the vertices')
    partition_count = len(partitions)
    for i in range(partition_count):
        for v in partitions[i]:
            if nx_graph.nodes[v] is None:
                raise ValueError('The partition must contain arrays of vertices in the graph')
            nx_graph.nodes[v]['subset'] = i
    for v in nx_graph.nodes:
        if 'subset' not in nx_graph.nodes[v]:
            nx_graph.nodes[v]['subset'] = partition_count
    return nx.layout.multipartite_layout(nx_graph, scale=scale, **kwargs)

def _random_layout(nx_graph: NxGraph, scale: float=2, **kwargs: Any):
    auto_layout = nx.layout.random_layout(nx_graph, **kwargs)
    for k, v in auto_layout.items():
        auto_layout[k] = 2 * scale * (v - np.array([0.5, 0.5]))
    return {k: np.append(v, [0]) for k, v in auto_layout.items()}

def _determine_graph_layout(nx_graph: nx.classes.graph.Graph | nx.classes.digraph.DiGraph, layout: LayoutName | dict[Hashable, Point3DLike] | LayoutFunction='spring', layout_scale: float | tuple[float, float, float]=2, layout_config: dict[str, Any] | None=None) -> dict[Hashable, Point3DLike]:
    if layout_config is None:
        layout_config = {}
    if isinstance(layout, dict):
        return layout
    elif layout in _layouts:
        auto_layout = _layouts[layout](nx_graph, scale=layout_scale, **layout_config)
        if layout_config.get('dim') == 3 or auto_layout[next(auto_layout.__iter__())].shape[0] == 3:
            return auto_layout
        else:
            return {k: np.append(v, [0]) for k, v in auto_layout.items()}
    else:
        try:
            return cast(LayoutFunction, layout)(nx_graph, scale=layout_scale, **layout_config)
        except TypeError as e:
            raise ValueError(f"The layout '{layout}' is neither a recognized layout, a layout function,nor a vertex placement dictionary.") from e

