def __init__(self, vertices: Sequence[Hashable], edges: Sequence[tuple[Hashable, Hashable]], labels: bool | dict=False, label_fill_color: str=BLACK, layout: LayoutName | dict[Hashable, Point3DLike] | LayoutFunction='spring', layout_scale: float | tuple[float, float, float]=2, layout_config: dict | None=None, vertex_type: type[Mobject]=Dot, vertex_config: dict | None=None, vertex_mobjects: dict | None=None, edge_type: type[Mobject]=Line, partitions: Sequence[Sequence[Hashable]] | None=None, root_vertex: Hashable | None=None, edge_config: dict | None=None) -> None:
    super().__init__()
    nx_graph = self._empty_networkx_graph()
    nx_graph.add_nodes_from(vertices)
    nx_graph.add_edges_from(edges)
    self._graph = nx_graph
    if isinstance(labels, dict):
        self._labels = labels
    elif isinstance(labels, bool):
        if labels:
            self._labels = {v: MathTex(v, fill_color=label_fill_color) for v in vertices}
        else:
            self._labels = {}
    if self._labels and vertex_type is Dot:
        vertex_type = LabeledDot
    if vertex_mobjects is None:
        vertex_mobjects = {}
    if vertex_config is None:
        vertex_config = {}
    default_vertex_config = {}
    if vertex_config:
        default_vertex_config = {k: v for k, v in vertex_config.items() if k not in vertices}
    self._vertex_config = {v: vertex_config.get(v, copy(default_vertex_config)) for v in vertices}
    self.default_vertex_config = default_vertex_config
    for v, label in self._labels.items():
        self._vertex_config[v]['label'] = label
    self.vertices = {v: vertex_type(**self._vertex_config[v]) for v in vertices}
    self.vertices.update(vertex_mobjects)
    self.change_layout(layout=layout, layout_scale=layout_scale, layout_config=layout_config, partitions=partitions, root_vertex=root_vertex)
    if edge_config is None:
        edge_config = {}
    default_tip_config = {}
    default_edge_config = {}
    if edge_config:
        default_tip_config = edge_config.pop('tip_config', {})
        default_edge_config = {k: v for k, v in edge_config.items() if not isinstance(k, tuple)}
    self._edge_config = {}
    self._tip_config = {}
    for e in edges:
        if e in edge_config:
            self._tip_config[e] = edge_config[e].pop('tip_config', copy(default_tip_config))
            self._edge_config[e] = edge_config[e]
        else:
            self._tip_config[e] = copy(default_tip_config)
            self._edge_config[e] = copy(default_edge_config)
    self.default_edge_config = default_edge_config
    self._populate_edge_dict(edges, edge_type)
    self.add(*self.vertices.values())
    self.add(*self.edges.values())
    self.add_updater(self.update_edges)

@staticmethod
def _empty_networkx_graph() -> nx.classes.graph.Graph:
    """Return an empty networkx graph for the given graph type."""
    raise NotImplementedError('To be implemented in concrete subclasses')

def _populate_edge_dict(self, edges: list[tuple[Hashable, Hashable]], edge_type: type[Mobject]):
    """Helper method for populating the edges of the graph."""
    raise NotImplementedError('To be implemented in concrete subclasses')

def _create_vertex(self, vertex: Hashable, position: Point3DLike | None=None, label: bool=False, label_fill_color: str=BLACK, vertex_type: type[Mobject]=Dot, vertex_config: dict | None=None, vertex_mobject: dict | None=None) -> tuple[Hashable, Point3D, dict, Mobject]:
    np_position: Point3D = self.get_center() if position is None else np.asarray(position)
    if vertex_config is None:
        vertex_config = {}
    if vertex in self.vertices:
        raise ValueError(f"Vertex identifier '{vertex}' is already used for a vertex in this graph.")
    if label is True:
        label = MathTex(vertex, fill_color=label_fill_color)
    elif vertex in self._labels:
        label = self._labels[vertex]
    elif not isinstance(label, (Mobject, OpenGLMobject)):
        label = None
    base_vertex_config = copy(self.default_vertex_config)
    base_vertex_config.update(vertex_config)
    vertex_config = base_vertex_config
    if label is not None:
        vertex_config['label'] = label
        if vertex_type is Dot:
            vertex_type = LabeledDot
    if vertex_mobject is None:
        vertex_mobject = vertex_type(**vertex_config)
    vertex_mobject.move_to(np_position)
    return (vertex, np_position, vertex_config, vertex_mobject)

def _create_vertices(self: Graph, *vertices: Hashable, positions: dict | None=None, labels: bool=False, label_fill_color: str=BLACK, vertex_type: type[Mobject]=Dot, vertex_config: dict | None=None, vertex_mobjects: dict | None=None) -> Iterable[tuple[Hashable, Point3D, dict, Mobject]]:
    if positions is None:
        positions = {}
    if vertex_mobjects is None:
        vertex_mobjects = {}
    graph_center = self.get_center()
    base_positions = dict.fromkeys(vertices, graph_center)
    base_positions.update(positions)
    positions = base_positions
    if isinstance(labels, bool):
        labels = dict.fromkeys(vertices, labels)
    else:
        assert isinstance(labels, dict)
        base_labels = dict.fromkeys(vertices, False)
        base_labels.update(labels)
        labels = base_labels
    if vertex_config is None:
        vertex_config = copy(self.default_vertex_config)
    assert isinstance(vertex_config, dict)
    base_vertex_config = copy(self.default_vertex_config)
    base_vertex_config.update({key: val for key, val in vertex_config.items() if key not in vertices})
    vertex_config = {v: vertex_config[v] if v in vertex_config else copy(base_vertex_config) for v in vertices}
    return [self._create_vertex(v, position=positions[v], label=labels[v], label_fill_color=label_fill_color, vertex_type=vertex_type, vertex_config=vertex_config[v], vertex_mobject=vertex_mobjects.get(v)) for v in vertices]

@override_animate(add_vertices)
def _add_vertices_animation(self, *args, anim_args=None, **kwargs):
    if anim_args is None:
        anim_args = {}
    animation = anim_args.pop('animation', Create)
    vertex_mobjects = self._create_vertices(*args, **kwargs)

    def on_finish(scene: Scene):
        for v in vertex_mobjects:
            scene.remove(v[-1])
            self._add_created_vertex(*v)
    return AnimationGroup(*(animation(v[-1], **anim_args) for v in vertex_mobjects), group=self, _on_finish=on_finish)

@override_animate(remove_vertices)
def _remove_vertices_animation(self, *vertices, anim_args=None):
    if anim_args is None:
        anim_args = {}
    animation = anim_args.pop('animation', Uncreate)
    mobjects = self.remove_vertices(*vertices)
    return AnimationGroup(*(animation(mobj, **anim_args) for mobj in mobjects), group=self)

@override_animate(add_edges)
def _add_edges_animation(self, *args, anim_args=None, **kwargs):
    if anim_args is None:
        anim_args = {}
    animation = anim_args.pop('animation', Create)
    mobjects = self.add_edges(*args, **kwargs)
    return AnimationGroup(*(animation(mobj, **anim_args) for mobj in mobjects), group=self)

@override_animate(remove_edges)
def _remove_edges_animation(self, *edges, anim_args=None):
    if anim_args is None:
        anim_args = {}
    animation = anim_args.pop('animation', Uncreate)
    mobjects = self.remove_edges(*edges)
    return AnimationGroup(*(animation(mobj, **anim_args) for mobj in mobjects))

def change_layout(self, layout: LayoutName | dict[Hashable, Point3DLike] | LayoutFunction='spring', layout_scale: float | tuple[float, float, float]=2, layout_config: dict[str, Any] | None=None, partitions: list[list[Hashable]] | None=None, root_vertex: Hashable | None=None) -> Graph:
    """Change the layout of this graph.

        See the documentation of :class:`~.Graph` for details about the
        keyword arguments.

        Examples
        --------

        .. manim:: ChangeGraphLayout

            class ChangeGraphLayout(Scene):
                def construct(self):
                    G = Graph([1, 2, 3, 4, 5], [(1, 2), (2, 3), (3, 4), (4, 5)],
                              layout={1: [-2, 0, 0], 2: [-1, 0, 0], 3: [0, 0, 0],
                                      4: [1, 0, 0], 5: [2, 0, 0]}
                              )
                    self.play(Create(G))
                    self.play(G.animate.change_layout("circular"))
                    self.wait()
        """
    layout_config = {} if layout_config is None else layout_config
    if partitions is not None and 'partitions' not in layout_config:
        layout_config['partitions'] = partitions
    if root_vertex is not None and 'root_vertex' not in layout_config:
        layout_config['root_vertex'] = root_vertex
    self._layout = _determine_graph_layout(self._graph, layout=layout, layout_scale=layout_scale, layout_config=layout_config)
    for v in self.vertices:
        self[v].move_to(self._layout[v])
    return self

@staticmethod
def _empty_networkx_graph() -> nx.Graph:
    return nx.Graph()

def update_edges(self, graph):
    for (u, v), edge in graph.edges.items():
        edge.set_points_by_ends(graph[u].get_center(), graph[v].get_center(), buff=self._edge_config.get('buff', 0), path_arc=self._edge_config.get('path_arc', 0))

@staticmethod
def _empty_networkx_graph() -> nx.DiGraph:
    return nx.DiGraph()

def _populate_edge_dict(self, edges: list[tuple[Hashable, Hashable]], edge_type: type[Mobject]):
    self.edges = {(u, v): edge_type(start=self[u], end=self[v], z_index=-1, **self._edge_config[u, v]) for u, v in edges}
    for (u, v), edge in self.edges.items():
        edge.add_tip(**self._tip_config[u, v])

def _organize_mob_matrix(self, matrix: list[list[Mobject]]) -> Self:
    for i, row in enumerate(matrix):
        for j, _ in enumerate(row):
            mob = matrix[i][j]
            mob.move_to(i * self.v_buff * DOWN + j * self.h_buff * RIGHT, self.element_alignment_corner)
    return self

@classmethod
def __init_subclass__(cls, **kwargs) -> None:
    super().__init_subclass__(**kwargs)
    cls.animation_overrides: dict[type[Animation], FunctionOverride] = {}
    cls._add_intrinsic_animation_overrides()
    cls._original__init__ = cls.__init__

def _assert_valid_submobjects_internal(self, submobjects: list[Mobject], mob_class: type[Mobject]) -> Self:
    for i, submob in enumerate(submobjects):
        if not isinstance(submob, mob_class):
            error_message = f'Only values of type {mob_class.__name__} can be added as submobjects of {type(self).__name__}, but the value {submob} (at index {i}) is of type {type(submob).__name__}.'
            if isinstance(submob, Mobject):
                error_message += ' You can try adding this value into a Group instead.'
            raise TypeError(error_message)
        if submob is self:
            raise ValueError(f'Cannot add {type(self).__name__} as a submobject of itself (at index {i}).')
    return self

@classmethod
def _add_intrinsic_animation_overrides(cls) -> None:
    """Initializes animation overrides marked with the :func:`~.override_animation`
        decorator.
        """
    for method_name in dir(cls):
        if method_name.startswith('__'):
            continue
        method = getattr(cls, method_name)
        if hasattr(method, '_override_animation'):
            animation_class = method._override_animation
            cls.add_animation_override(animation_class, method)

def reset_points(self) -> None:
    """Sets :attr:`points` to be an empty array."""
    self.points = np.zeros((0, self.dim))

def __getattr__(self, attr: str) -> types.MethodType:
    if attr.startswith('get_'):
        to_get = attr[4:]

        def getter(self):
            warnings.warn('This method is not guaranteed to stay around. Please prefer getting the attribute normally.', DeprecationWarning, stacklevel=2)
            return getattr(self, to_get)
        return types.MethodType(getter, self)
    if attr.startswith('set_'):
        to_set = attr[4:]

        def setter(self, value):
            warnings.warn('This method is not guaranteed to stay around. Please prefer setting the attribute normally or with Mobject.set().', DeprecationWarning, stacklevel=2)
            setattr(self, to_set, value)
            return self
        return types.MethodType(setter, self)
    raise AttributeError(f"{type(self).__name__} object has no attribute '{attr}'")

@width.setter
def width(self, value: float):
    self.scale_to_fit_width(value)

@height.setter
def height(self, value: float):
    self.scale_to_fit_height(value)

@depth.setter
def depth(self, value: float):
    self.scale_to_fit_depth(value)

def apply_over_attr_arrays(self, func: MultiMappingFunction) -> Self:
    for attr in self.get_array_attrs():
        setattr(self, attr, func(getattr(self, attr)))
    return self

def get_image(self, camera=None) -> PixelArray:
    if camera is None:
        from ..camera.camera import Camera
        camera = Camera()
    camera.capture_mobject(self)
    return camera.get_image()

def generate_target(self, use_deepcopy: bool=False) -> Self:
    self.target = None
    if use_deepcopy:
        self.target = copy.deepcopy(self)
    else:
        self.target = self.copy()
    return self.target

def rotate_about_origin(self, angle: float, axis: Vector3DLike=OUT) -> Self:
    """Rotates the :class:`~.Mobject` about the ORIGIN, which is at [0,0,0]."""
    return self.rotate(angle, axis, about_point=ORIGIN)

def stretch(self, factor: float, dim: int, **kwargs) -> Self:

    def func(points: Point3D_Array) -> Point3D_Array:
        points[:, dim] *= factor
        return points
    self.apply_points_function_about_point(func, **kwargs)
    return self

def apply_function(self, function: MappingFunction, **kwargs) -> Self:
    if len(kwargs) == 0:
        kwargs['about_point'] = ORIGIN

    def multi_mapping_function(points: Point3D_Array) -> Point3D_Array:
        result: Point3D_Array = np.apply_along_axis(function, 1, points)
        return result
    self.apply_points_function_about_point(multi_mapping_function, **kwargs)
    return self

def apply_function_to_position(self, function: MappingFunction) -> Self:
    self.move_to(function(self.get_center()))
    return self

def apply_function_to_submobject_positions(self, function: MappingFunction) -> Self:
    for submob in self.submobjects:
        submob.apply_function_to_position(function)
    return self

def reverse_points(self) -> Self:
    for mob in self.family_members_with_points():
        mob.apply_over_attr_arrays(lambda arr: np.array(list(reversed(arr))))
    return self

def repeat(self, count: int) -> Self:
    """This can make transition animations nicer"""

    def repeat_array(array):
        return reduce(lambda a1, a2: np.append(a1, a2, axis=0), [array] * count)
    for mob in self.family_members_with_points():
        mob.apply_over_attr_arrays(repeat_array)
    return self

def apply_points_function_about_point(self, func: MultiMappingFunction, about_point: Point3DLike | None=None, about_edge: Vector3DLike | None=None) -> Self:
    if about_point is None:
        if about_edge is None:
            about_edge = ORIGIN
        about_point = self.get_critical_point(about_edge)
    for mob in self.family_members_with_points():
        mob.points -= about_point
        mob.points = func(mob.points)
        mob.points += about_point
    return self

def pose_at_angle(self, **kwargs):
    self.rotate(TAU / 14, RIGHT + UP, **kwargs)
    return self

def shift_onto_screen(self, **kwargs) -> Self:
    space_lengths = [config['frame_x_radius'], config['frame_y_radius']]
    for vect in (UP, DOWN, LEFT, RIGHT):
        dim = np.argmax(np.abs(vect))
        buff = kwargs.get('buff', DEFAULT_MOBJECT_TO_EDGE_BUFFER)
        max_val = space_lengths[dim] - buff
        edge_center = self.get_edge_center(vect)
        if np.dot(edge_center, vect) > max_val:
            self.to_edge(vect, **kwargs)
    return self

def is_off_screen(self):
    if self.get_left()[0] > config['frame_x_radius']:
        return True
    if self.get_right()[0] < -config['frame_x_radius']:
        return True
    if self.get_bottom()[1] > config['frame_y_radius']:
        return True
    return self.get_top()[1] < -config['frame_y_radius']

def rescale_to_fit(self, length: float, dim: int, stretch: bool=False, **kwargs) -> Self:
    old_length = self.length_over_dim(dim)
    if old_length == 0:
        return self
    if stretch:
        self.stretch(length / old_length, dim, **kwargs)
    else:
        self.scale(length / old_length, **kwargs)
    return self

def scale_to_fit_depth(self, depth: float, **kwargs) -> Self:
    """Scales the :class:`~.Mobject` to fit a depth while keeping width/height proportional."""
    return self.rescale_to_fit(depth, 2, stretch=False, **kwargs)

def stretch_to_fit_depth(self, depth: float, **kwargs) -> Self:
    """Stretches the :class:`~.Mobject` to fit a depth, not keeping width/height proportional."""
    return self.rescale_to_fit(depth, 2, stretch=True, **kwargs)

def set_x(self, x: float, direction: Vector3DLike=ORIGIN) -> Self:
    """Set x value of the center of the :class:`~.Mobject` (``int`` or ``float``)"""
    return self.set_coord(x, 0, direction)

def set_y(self, y: float, direction: Vector3DLike=ORIGIN) -> Self:
    """Set y value of the center of the :class:`~.Mobject` (``int`` or ``float``)"""
    return self.set_coord(y, 1, direction)

def set_z(self, z: float, direction: Vector3DLike=ORIGIN) -> Self:
    """Set z value of the center of the :class:`~.Mobject` (``int`` or ``float``)"""
    return self.set_coord(z, 2, direction)

def space_out_submobjects(self, factor: float=1.5, **kwargs) -> Self:
    self.scale(factor, **kwargs)
    for submob in self.submobjects:
        submob.scale(1.0 / factor)
    return self

def move_to(self, point_or_mobject: Point3DLike | Mobject, aligned_edge: Vector3DLike=ORIGIN, coor_mask: Vector3DLike=np.array([1, 1, 1])) -> Self:
    """Move center of the :class:`~.Mobject` to certain Point3D."""
    if isinstance(point_or_mobject, Mobject):
        target = point_or_mobject.get_critical_point(aligned_edge)
    else:
        target = point_or_mobject
    point_to_align = self.get_critical_point(aligned_edge)
    self.shift((target - point_to_align) * coor_mask)
    return self

def replace(self, mobject: Mobject, dim_to_match: int=0, stretch: bool=False) -> Self:
    if not mobject.get_num_points() and (not mobject.submobjects):
        raise Warning('Attempting to replace mobject with no points')
    if stretch:
        self.stretch_to_fit_width(mobject.width)
        self.stretch_to_fit_height(mobject.height)
    else:
        self.rescale_to_fit(mobject.length_over_dim(dim_to_match), dim_to_match, stretch=False)
    self.shift(mobject.get_center() - self.get_center())
    return self

def add_background_rectangle_to_submobjects(self, **kwargs) -> Self:
    for submobject in self.submobjects:
        submobject.add_background_rectangle(**kwargs)
    return self

def add_background_rectangle_to_family_members_with_points(self, **kwargs) -> Self:
    for mob in self.family_members_with_points():
        mob.add_background_rectangle(**kwargs)
    return self

def set_colors_by_radial_gradient(self, center: Point3DLike | None=None, radius: float=1, inner_color: ParsableManimColor=WHITE, outer_color: ParsableManimColor=BLACK) -> Self:
    self.set_submobject_colors_by_radial_gradient(center, radius, inner_color, outer_color)
    return self

def set_submobject_colors_by_gradient(self, *colors: Iterable[ParsableManimColor]):
    if len(colors) == 0:
        raise ValueError('Need at least one color')
    elif len(colors) == 1:
        return self.set_color(*colors)
    mobs = self.family_members_with_points()
    new_colors = color_gradient(colors, len(mobs))
    for mob, color in zip(mobs, new_colors):
        mob.set_color(color, family=False)
    return self

def set_submobject_colors_by_radial_gradient(self, center: Point3DLike | None=None, radius: float=1, inner_color: ParsableManimColor=WHITE, outer_color: ParsableManimColor=BLACK) -> Self:
    if center is None:
        center = self.get_center()
    for mob in self.family_members_with_points():
        t = np.linalg.norm(mob.get_center() - center) / radius
        t = min(t, 1)
        mob_color = interpolate_color(inner_color, outer_color, t)
        mob.set_color(mob_color, family=False)
    return self

def to_original_color(self) -> Self:
    self.set_color(self.color)
    return self

def fade_to(self, color: ParsableManimColor, alpha: float, family: bool=True) -> Self:
    if self.get_num_points() > 0:
        new_color = interpolate_color(self.get_color(), color, alpha)
        self.set_color(new_color, family=False)
    if family:
        for submob in self.submobjects:
            submob.fade_to(color, alpha)
    return self

def fade(self, darkness: float=0.5, family: bool=True) -> Self:
    if family:
        for submob in self.submobjects:
            submob.fade(darkness, family)
    return self

def save_state(self) -> Self:
    """Save the current state (position, color & size). Can be restored with :meth:`~.Mobject.restore`."""
    if hasattr(self, 'saved_state'):
        self.saved_state = None
    self.saved_state = self.copy()
    return self

def restore(self) -> Self:
    """Restores the state that was previously saved with :meth:`~.Mobject.save_state`."""
    if not hasattr(self, 'saved_state') or self.save_state is None:
        raise Exception('Trying to restore without having saved')
    self.become(self.saved_state)
    return self

def reduce_across_dimension(self, reduce_func: Callable, dim: int):
    """Find the min or max value from a dimension across all points in this and submobjects."""
    assert dim >= 0
    assert dim <= 2
    if len(self.submobjects) == 0 and len(self.points) == 0:
        return 0
    if len(self.points) == 0:
        rv = None
    else:
        rv = reduce_func(self.points[:, dim])
    for mobj in self.submobjects:
        value = mobj.reduce_across_dimension(reduce_func, dim)
        rv = value if rv is None else reduce_func([value, rv])
    return rv

def get_all_points(self) -> Point3D_Array:
    """Return all points from this mobject and all submobjects.

        May contain duplicates; the order is in a depth-first (pre-order)
        traversal of the submobjects.
        """
    return self.get_merged_array('points')

def get_extremum_along_dim(self, points: Point3DLike_Array | None=None, dim: int=0, key: int=0) -> float:
    np_points: Point3D_Array = self.get_points_defining_boundary() if points is None else np.asarray(points)
    values = np_points[:, dim]
    if key < 0:
        return np.min(values)
    elif key == 0:
        return (np.min(values) + np.max(values)) / 2
    else:
        return np.max(values)

def get_edge_center(self, direction: Vector3DLike) -> Point3D:
    """Get edge Point3Ds for certain direction."""
    return self.get_critical_point(direction)

def get_corner(self, direction: Vector3DLike) -> Point3D:
    """Get corner Point3Ds for certain direction."""
    return self.get_critical_point(direction)

def get_center(self) -> Point3D:
    """Get center Point3Ds"""
    return self.get_critical_point(np.zeros(self.dim))

def get_top(self) -> Point3D:
    """Get top Point3Ds of a box bounding the :class:`~.Mobject`"""
    return self.get_edge_center(UP)

def get_bottom(self) -> Point3D:
    """Get bottom Point3Ds of a box bounding the :class:`~.Mobject`"""
    return self.get_edge_center(DOWN)

def get_right(self) -> Point3D:
    """Get right Point3Ds of a box bounding the :class:`~.Mobject`"""
    return self.get_edge_center(RIGHT)

def get_left(self) -> Point3D:
    """Get left Point3Ds of a box bounding the :class:`~.Mobject`"""
    return self.get_edge_center(LEFT)

def get_zenith(self) -> Point3D:
    """Get zenith Point3Ds of a box bounding a 3D :class:`~.Mobject`."""
    return self.get_edge_center(OUT)

def get_nadir(self) -> Point3D:
    """Get nadir (opposite the zenith) Point3Ds of a box bounding a 3D :class:`~.Mobject`."""
    return self.get_edge_center(IN)

def length_over_dim(self, dim: int) -> float:
    """Measure the length of an :class:`~.Mobject` in a certain direction."""
    return self.reduce_across_dimension(max, dim) - self.reduce_across_dimension(min, dim)

def get_coord(self, dim: int, direction: Vector3DLike=ORIGIN) -> float:
    """Meant to generalize ``get_x``, ``get_y`` and ``get_z``"""
    return self.get_extremum_along_dim(dim=dim, key=direction[dim])

