def __init__(self, func: Callable[[Point3D], Vector3D], color: ParsableManimColor | None=None, color_scheme: Callable[[Vector3D], float] | None=None, min_color_scheme_value: float=0, max_color_scheme_value: float=2, colors: Sequence[ParsableManimColor]=DEFAULT_SCALAR_FIELD_COLORS, **kwargs):
    super().__init__(**kwargs)
    self.func = func
    if color is None:
        self.single_color = False
        if color_scheme is None:

            def color_scheme(vec: Vector3D) -> float:
                return np.linalg.norm(vec)
        self.color_scheme = color_scheme
        self.rgbs: FloatRGB_Array = np.array(list(map(color_to_rgb, colors)))

        def pos_to_rgb(pos: Point3D) -> FloatRGB:
            vec = self.func(pos)
            color_value = np.clip(self.color_scheme(vec), min_color_scheme_value, max_color_scheme_value)
            alpha = inverse_interpolate(min_color_scheme_value, max_color_scheme_value, color_value)
            alpha *= len(self.rgbs) - 1
            c1: FloatRGB = self.rgbs[int(alpha)]
            c2: FloatRGB = self.rgbs[min(int(alpha + 1), len(self.rgbs) - 1)]
            alpha %= 1
            return interpolate(c1, c2, alpha)
        self.pos_to_rgb = pos_to_rgb
        self.pos_to_color = lambda pos: rgb_to_color(self.pos_to_rgb(pos))
    else:
        self.single_color = True
        self.color = ManimColor.parse(color)
    self.submob_movement_updater = None

