def __init__(self, frame_shape=None, center_point=None, euler_angles=[0, 0, 0], focal_distance=2, light_source_position=[-10, 10, 10], orthographic=False, minimum_polar_angle=-PI / 2, maximum_polar_angle=PI / 2, model_matrix=None, **kwargs):
    self.use_z_index = True
    self.frame_rate = 60
    self.orthographic = orthographic
    self.minimum_polar_angle = minimum_polar_angle
    self.maximum_polar_angle = maximum_polar_angle
    if self.orthographic:
        self.projection_matrix = opengl.orthographic_projection_matrix()
