def render_mobject(self, mobject):
    if isinstance(mobject, OpenGLVMobject):
        if config['use_projection_fill_shaders']:
            render_opengl_vectorized_mobject_fill(self, mobject)
        if config['use_projection_stroke_shaders']:
            render_opengl_vectorized_mobject_stroke(self, mobject)
    shader_wrapper_list = mobject.get_shader_wrapper_list()
    for shader_wrapper in shader_wrapper_list:
        shader = Shader(self.context, shader_wrapper.shader_folder)
        for name, path in shader_wrapper.texture_paths.items():
            tid = self.get_texture_id(path)
            shader.shader_program[name].value = tid
        for name, value in it.chain(shader_wrapper.uniforms.items(), self.perspective_uniforms.items()):
            with contextlib.suppress(KeyError):
                shader.set_uniform(name, value)
        try:
            shader.set_uniform('u_view_matrix', self.scene.camera.formatted_view_matrix)
            shader.set_uniform('u_projection_matrix', self.scene.camera.projection_matrix)
        except KeyError:
            pass
        if shader_wrapper.depth_test:
            self.context.enable(moderngl.DEPTH_TEST)
        else:
            self.context.disable(moderngl.DEPTH_TEST)
        mesh = Mesh(shader, shader_wrapper.vert_data, indices=shader_wrapper.vert_indices, use_depth_test=shader_wrapper.depth_test, primitive=mobject.render_primitive)
        mesh.set_uniforms(self)
        mesh.render()

@handle_caching_play
def play(self, scene: Scene, *args: Animation | Mobject | _AnimationBuilder, **kwargs: Any) -> None:
    self.animation_start_time = time.time()
    self.file_writer.begin_animation(not self.skip_animations)
    scene.compile_animation_data(*args, **kwargs)
    scene.begin_animations()
    if scene.is_current_animation_frozen_frame():
        self.update_frame(scene)
        if not self.skip_animations:
            self.file_writer.write_frame(self, num_frames=int(config.frame_rate * scene.duration))
        if self.window is not None:
            self.window.swap_buffers()
            while time.time() - self.animation_start_time < scene.duration:
                pass
        self.animation_elapsed_time = scene.duration
    else:
        scene.play_internal()
    self.file_writer.end_animation(not self.skip_animations)
    self.time += scene.duration
    self.num_plays += 1

def clear_screen(self) -> None:
    self.frame_buffer_object.clear(*self.background_color)
    self.window.swap_buffers()

def render(self, scene: Scene, frame_offset, moving_mobjects: list[Mobject]) -> None:
    self.update_frame(scene)
    if self.skip_animations:
        return
    self.file_writer.write_frame(self)
    if self.window is not None:
        self.window.swap_buffers()
        while self.animation_elapsed_time < frame_offset:
            self.update_frame(scene)
            self.window.swap_buffers()

def update_frame(self, scene):
    self.frame_buffer_object.clear(*self.background_color)
    self.refresh_perspective_uniforms(scene.camera)
    for mobject in scene.mobjects:
        if not mobject.should_render:
            continue
        self.render_mobject(mobject)
    for obj in scene.meshes:
        for mesh in obj.get_meshes():
            mesh.set_uniforms(self)
            mesh.render()
    self.animation_elapsed_time = time.time() - self.animation_start_time

def scene_finished(self, scene):
    if self.num_plays > 0:
        self.file_writer.finish()
    elif self.num_plays == 0 and config.write_to_movie:
        config.write_to_movie = False
    if self.should_save_last_frame():
        config.save_last_frame = True
        self.update_frame(scene)
        self.file_writer.save_image(self.get_image())

def should_save_last_frame(self):
    if config['save_last_frame']:
        return True
    if self.scene.interactive_mode:
        return False
    return self.num_plays == 0

def get_frame_buffer_object(self, context, samples=0):
    pixel_width = config['pixel_width']
    pixel_height = config['pixel_height']
    num_channels = 4
    return context.framebuffer(color_attachments=context.texture((pixel_width, pixel_height), components=num_channels, samples=samples), depth_attachment=context.depth_renderbuffer((pixel_width, pixel_height), samples=samples))

def pixel_coords_to_space_coords(self, px: float, py: float, relative: bool=False, top_left: bool=False) -> Point3D:
    pixel_shape = self.get_pixel_shape()
    if pixel_shape is None:
        return np.array([0, 0, 0])
    pw, ph = pixel_shape
    fh = config['frame_height']
    fc = self.camera.get_center()
    if relative:
        return 2 * np.array([px / pw, py / ph, 0])
    else:
        scale = fh / ph
        return fc + scale * np.array([px - pw / 2, (-1 if top_left else 1) * (py - ph / 2), 0])

