        if dtype_name in attributes:
            filtered_attributes_dtype.append((dtype_name, unfiltered_attributes.dtype[i].subdtype[0].str, unfiltered_attributes.dtype[i].shape))
    filtered_attributes = np.zeros(unfiltered_attributes[unfiltered_attributes.dtype.names[0]].shape[0], dtype=filtered_attributes_dtype)
    for dtype_name in unfiltered_attributes.dtype.names:
        if dtype_name in attributes:
            filtered_attributes[dtype_name] = unfiltered_attributes[dtype_name]
    return filtered_attributes

methods.signature:
def interpolate(self, start: Object3D, end: Object3D, alpha: float, _: Any) -> None:
    self.model_matrix = (1 - alpha) * start.model_matrix + alpha * end.model_matrix
    self.normal_matrix = (1 - alpha) * start.normal_matrix + alpha * end.normal_matrix

def copy(self) -> Object3D:
    node_to_copy = {}
    bfs = [self]
    while bfs:
        node = bfs.pop(0)
        bfs.extend(node.children)
        node_copy = node.single_copy()
        node_to_copy[node] = node_copy
        if node.parent is not None and node is not self:
            node_to_copy[node.parent].add(node_copy)
    return node_to_copy[self]

def add(self, *children: Object3D) -> None:
    for child in children:
        if child.parent is not None:
            raise Exception("Attempt to add child that's already added to another Object3D")
    self.remove(*children, current_children_only=False)
    self.children.extend(children)
    for child in children:
        child.parent = self

def remove(self, *children: Object3D, current_children_only: bool=True) -> None:
    if current_children_only:
        for child in children:
            if child.parent != self:
                raise Exception("Attempt to remove child that isn't added to this Object3D")
    self.children = list(filter(lambda child: child not in children, self.children))
    for child in children:
        child.parent = None

def set_position(self, position: Point3D) -> Self:
    self.model_matrix[:, 3][:3] = position
    return self

def get_meshes(self) -> Iterator[Mesh]:
    dfs = [self]
    while dfs:
        parent = dfs.pop()
        if isinstance(parent, Mesh):
            yield parent
        dfs.extend(parent.children)

def get_family(self) -> Iterator[Object3D]:
    dfs = [self]
    while dfs:
        parent = dfs.pop()
        yield parent
        dfs.extend(parent.children)

def hierarchical_model_matrix(self) -> MatrixMN:
    if self.parent is None:
        return self.model_matrix
    model_matrices = [self.model_matrix]
    current_object = self
    while current_object.parent is not None:
        model_matrices.append(current_object.parent.model_matrix)
        current_object = current_object.parent
    return np.linalg.multi_dot(list(reversed(model_matrices)))

def hierarchical_normal_matrix(self) -> MatrixMN:
    if self.parent is None:
        return self.normal_matrix[:3, :3]
    normal_matrices = [self.normal_matrix]
    current_object = self
    while current_object.parent is not None:
        normal_matrices.append(current_object.parent.model_matrix)
        current_object = current_object.parent
    return np.linalg.multi_dot(list(reversed(normal_matrices)))[:3, :3]

def update(self, dt: float=0) -> Self:
    if not self.has_updaters or self.updating_suspended:
        return self
    for time_based_updater in self.time_based_updaters:
        time_based_updater(self, dt)
    for non_time_based_updater in self.non_time_updaters:
        non_time_based_updater(self)
    return self

def add_updater(self, update_function: MeshUpdater, index: int | None=None, call_updater: bool=True) -> Self:
    if 'dt' in inspect.signature(update_function).parameters:
        self._add_time_based_updater(update_function, index)
    else:
        self._add_non_time_updater(update_function, index)
    self.refresh_has_updater_status()
    if call_updater:
        self.update()
    return self

def _add_time_based_updater(self, update_function: MeshTimeBasedUpdater, index: int | None=None) -> None:
    if index is None:
        self.time_based_updaters.append(update_function)
    else:
        self.time_based_updaters.insert(index, update_function)

def _add_non_time_updater(self, update_function: MeshNonTimeBasedUpdater, index: int | None=None) -> None:
    if index is None:
        self.non_time_updaters.append(update_function)
    else:
        self.non_time_updaters.insert(index, update_function)

def remove_updater(self, update_function: MeshUpdater) -> Self:
    while update_function in self.time_based_updaters:
        self.time_based_updaters.remove(update_function)
    while update_function in self.non_time_updaters:
        self.non_time_updaters.remove(update_function)
    self.refresh_has_updater_status()
    return self

def match_updaters(self, mesh: Object3D) -> Self:
    self.clear_updaters()
    for updater in mesh.get_updaters():
        self.add_updater(updater)
    return self

def suspend_updating(self) -> Self:
    self.updating_suspended = True
    return self

def resume_updating(self, call_updater: bool=True) -> Self:
    self.updating_suspended = False
    if call_updater:
        self.update(dt=0)
    return self

def refresh_has_updater_status(self) -> Self:
    self.has_updaters = len(self.get_updaters()) > 0
    return self

def render(self) -> None:
    if self.skip_render:
        return
    if self.use_depth_test:
        self.shader.context.enable(moderngl.DEPTH_TEST)
    else:
        self.shader.context.disable(moderngl.DEPTH_TEST)
    shader_attribute_names: list[str] = []
    for member_name, member in self.shader.shader_program._members.items():
        if isinstance(member, moderngl.Attribute):
            shader_attribute_names.append(member_name)
    filtered_shader_attributes = filter_attributes(self.attributes, shader_attribute_names)
    vertex_buffer_object = self.shader.context.buffer(filtered_shader_attributes.tobytes())
    if self.indices is None:
        index_buffer_object = None
    else:
        vert_index_data = self.indices.astype('i4').tobytes()
        if vert_index_data:
            index_buffer_object = self.shader.context.buffer(vert_index_data)
        else:
            index_buffer_object = None
    vertex_array_object = self.shader.context.simple_vertex_array(self.shader.shader_program, vertex_buffer_object, *filtered_shader_attributes.dtype.names, index_buffer=index_buffer_object)
    vertex_array_object.render(self.primitive)
    vertex_buffer_object.release()
    vertex_array_object.release()
    if index_buffer_object is not None:
        index_buffer_object.release()

def __init__(self, context: moderngl.Context, name: str | None=None, source: dict[str, Any] | None=None):
    global shader_program_cache
    self.context = context
    self.name = name
    self.source = source
    if self.name in shader_program_cache and shader_program_cache[self.name].ctx == self.context:
        self.shader_program = shader_program_cache[self.name]
    elif self.source is not None:
        self.shader_program = context.program(**self.source)
    elif self.name is not None:
        source_dict = {}
        source_dict_key = {'vert': 'vertex_shader', 'frag': 'fragment_shader', 'geom': 'geometry_shader'}
        shader_folder = SHADER_FOLDER / self.name
        for shader_file in shader_folder.iterdir():
            shader_file_path = shader_folder / shader_file
            shader_source = get_shader_code_from_file(shader_file_path)
            source_dict[source_dict_key[shader_file_path.stem]] = shader_source
        self.shader_program = context.program(**source_dict)
    else:
        raise Exception('Must either pass shader name or shader source.')
    if self.name is not None and self.name not in shader_program_cache:
        shader_program_cache[self.name] = self.shader_program

def set_uniform(self, name: str, value: Any) -> None:
    with contextlib.suppress(KeyError):
        self.shader_program[name] = value

signature:
def find_file(file_name: Path, directories: list[Path]) -> Path:
    if file_name.exists():
        return file_name
    possible_paths = (directory / file_name for directory in directories)
    for path in possible_paths:
        if path.exists():
            return path
        else:
            logger.debug(f'{path} does not exist.')
    raise OSError(f'{file_name} not Found')

methods.signature:
def copy(self):
    result = copy.copy(self)
    result.vert_data = np.array(self.vert_data)
    if result.vert_indices is not None:
        result.vert_indices = np.array(self.vert_indices)
    if self.uniforms:
        result.uniforms = dict(self.uniforms)
    if self.texture_paths:
        result.texture_paths = dict(self.texture_paths)
    return result

def refresh_id(self) -> None:
    self.program_id: int = self.create_program_id()
    self.id: str = self.create_id()

def init_program_code(self):

    def get_code(name: str) -> str | None:
        return get_shader_code_from_file(self.shader_folder / f'{name}.glsl')
    self.program_code: dict[str, str | None] = {'vertex_shader': get_code('vert'), 'geometry_shader': get_code('geom'), 'fragment_shader': get_code('frag')}

def replace_code(self, old: str, new: str) -> None:
    code_map = self.program_code
    for name, _code in code_map.items():
        if code_map[name] is None:
            continue
        code_map[name] = re.sub(old, new, code_map[name])
    self.refresh_id()

def combine_with(self, *shader_wrappers: 'ShaderWrapper') -> Self:
    if len(shader_wrappers) == 0:
        return self
    if self.vert_indices is not None:
        num_verts = len(self.vert_data)
        indices_list = [self.vert_indices]
        data_list = [self.vert_data]
        for sw in shader_wrappers:
            indices_list.append(sw.vert_indices + num_verts)
            data_list.append(sw.vert_data)
            num_verts += len(sw.vert_data)
        self.vert_indices = np.hstack(indices_list)
        self.vert_data = np.hstack(data_list)
    else:
        self.vert_data = np.hstack([self.vert_data, *(sw.vert_data for sw in shader_wrappers)])
    return self

signature:
def get_shader_code_from_file(filename: Path) -> str | None:
    if filename in filename_to_code_map:
        return filename_to_code_map[filename]
    try:
        filepath = find_file(filename, directories=[get_shader_dir(), Path('/')])
    except OSError:
        return None
    result = filepath.read_text()
    insertions = re.findall('^#include ../include/.*\\.glsl$', result, flags=re.MULTILINE)
    for line in insertions:
        inserted_code = get_shader_code_from_file(Path() / 'include' / line.replace('#include ../include/', ''))
        if inserted_code is None:
            return None
        result = result.replace(line, inserted_code)
    filename_to_code_map[filename] = result
    return result

def get_colormap_code(rgb_list: FloatRGBLike_Array) -> str:
    data = ','.join(('vec3({}, {}, {})'.format(*rgb) for rgb in rgb_list))
    return f'vec3[{len(rgb_list)}]({data})'

def build_matrix_lists(mob: OpenGLVMobject) -> defaultdict[tuple[float, ...], list[OpenGLVMobject]]:
    root_hierarchical_matrix = mob.hierarchical_model_matrix()
    matrix_to_mobject_list = defaultdict(list)
    if mob.has_points():
        matrix_to_mobject_list[tuple(root_hierarchical_matrix.ravel())].append(mob)
    mobject_to_hierarchical_matrix = {mob: root_hierarchical_matrix}
    dfs = [mob]
    while dfs:
        parent = dfs.pop()
        for child in parent.submobjects:
            child_hierarchical_matrix = mobject_to_hierarchical_matrix[parent] @ child.model_matrix
            mobject_to_hierarchical_matrix[child] = child_hierarchical_matrix
            if child.has_points():
                matrix_to_mobject_list[tuple(child_hierarchical_matrix.ravel())].append(child)
            dfs.append(child)
    return matrix_to_mobject_list

def render_opengl_vectorized_mobject_fill(renderer: OpenGLRenderer, mobject: OpenGLVMobject) -> None:
    matrix_to_mobject_list = build_matrix_lists(mobject)
    for matrix_tuple, mobject_list in matrix_to_mobject_list.items():
        model_matrix = np.array(matrix_tuple).reshape((4, 4))
        render_mobject_fills_with_matrix(renderer, model_matrix, mobject_list)

def render_opengl_vectorized_mobject_stroke(renderer: OpenGLRenderer, mobject: OpenGLVMobject) -> None:
    matrix_to_mobject_list = build_matrix_lists(mobject)
    for matrix_tuple, mobject_list in matrix_to_mobject_list.items():
        model_matrix = np.array(matrix_tuple).reshape((4, 4))
        render_mobject_strokes_with_matrix(renderer, model_matrix, mobject_list)

