def init_output_directories(self, scene_name: str) -> None:
    """Initialise output directories.

        Notes
        -----
        The directories are read from ``config``, for example
        ``config['media_dir']``.  If the target directories don't already
        exist, they will be created.

        """
    if config['dry_run']:
        return
    module_name = config.get_dir('input_file').stem if config['input_file'] else ''
    if SceneFileWriter.force_output_as_scene_name:
        self.output_name = Path(scene_name)
    elif config['output_file'] and (not config['write_all']):
        self.output_name = config.get_dir('output_file')
    else:
        self.output_name = Path(scene_name)
    if config['media_dir']:
        image_dir = guarantee_existence(config.get_dir('images_dir', module_name=module_name, scene_name=scene_name))
        self.image_file_path = image_dir / add_extension_if_not_present(self.output_name, '.png')
    if write_to_movie():
        movie_dir = guarantee_existence(config.get_dir('video_dir', module_name=module_name, scene_name=scene_name))
        self.movie_file_path = movie_dir / add_extension_if_not_present(self.output_name, config['movie_file_extension'])
        self.sections_output_dir = Path('')
        if config.save_sections:
            self.sections_output_dir = guarantee_existence(config.get_dir('sections_dir', module_name=module_name, scene_name=scene_name))
        if is_gif_format():
            self.gif_file_path = add_extension_if_not_present(self.output_name, '.gif')
            if not config['output_file']:
                self.gif_file_path = add_version_before_extension(self.gif_file_path)
            self.gif_file_path = movie_dir / self.gif_file_path
        self.partial_movie_directory = guarantee_existence(config.get_dir('partial_movie_dir', scene_name=scene_name, module_name=module_name))
        if config['log_to_file']:
            log_dir = guarantee_existence(config.get_dir('log_dir'))
            set_file_logger(scene_name=scene_name, module_name=module_name, log_dir=log_dir)

def finish_last_section(self) -> None:
