    """Will clean the cache by removing the oldest partial_movie_files."""
    cached_partial_movies = [self.partial_movie_directory / file_name for file_name in self.partial_movie_directory.iterdir() if file_name != 'partial_movie_file_list.txt']
    if len(cached_partial_movies) > config['max_files_cached']:
        number_files_to_delete = len(cached_partial_movies) - config['max_files_cached']
        oldest_files_to_delete = sorted(cached_partial_movies, key=lambda path: path.stat().st_atime)[:number_files_to_delete]
        for file_to_delete in oldest_files_to_delete:
            file_to_delete.unlink()
        logger.info(f"The partial movie directory is full (> {config['max_files_cached']} files). Therefore, manim has removed the {number_files_to_delete} oldest file(s). You can change this behaviour by changing max_files_cached in config.")

