def get_video_metadata(path_to_video: str | os.PathLike) -> VideoMetadata:
    with av.open(str(path_to_video)) as container:
        stream = container.streams.video[0]
        ctxt = stream.codec_context
        rate = stream.average_rate
        if stream.duration is not None:
            duration = float(stream.duration * stream.time_base)
            num_frames = stream.frames
        else:
            num_frames = sum((1 for _ in container.decode(video=0)))
            duration = float(num_frames / stream.base_rate)
        return {'width': ctxt.width, 'height': ctxt.height, 'nb_frames': str(num_frames), 'duration': f'{duration:.6f}', 'avg_frame_rate': f'{rate.numerator}/{rate.denominator}', 'codec_name': stream.codec_context.name, 'pix_fmt': stream.codec_context.pix_fmt}

def get_dir_layout(dirpath: Path) -> Generator[str, None, None]:
    """Get list of paths relative to dirpath of all files in dir and subdirs recursively."""
    for p in dirpath.iterdir():
        if p.is_dir():
            yield from get_dir_layout(p)
            continue
        yield str(p.relative_to(dirpath))

def merge_dicts_recursively(*dicts: dict[Any, Any]) -> dict[Any, Any]:
    """
    Creates a dict whose keyset is the union of all the
    input dictionaries.  The value for each key is based
    on the first dict in the list with that key.

    dicts later in the list have higher priority

    When values are dictionaries, it is applied recursively
    """
    result: dict = {}
    all_items = it.chain(*(d.items() for d in dicts))
    for key, value in all_items:
        if key in result and isinstance(result[key], dict) and isinstance(value, dict):
            result[key] = merge_dicts_recursively(result[key], value)
        else:
            result[key] = value
    return result

def update_dict_recursively(current_dict: dict[Any, Any], *others: dict[Any, Any]) -> None:
    updated_dict = merge_dicts_recursively(current_dict, *others)
    current_dict.update(updated_dict)

