def tuplify(obj: str | Iterable[T] | T) -> tuple[str] | tuple[T]:
    """Converts obj to a tuple intelligently.

    Examples
    --------
    .. code-block:: pycon

        >>> tuplify("str")
        ('str',)
        >>> tuplify([1, 2])
        (1, 2)
        >>> tuplify(len)
        (<built-in function len>,)
    """
    if isinstance(obj, str):
        return (obj,)
    if isinstance(obj, Iterable):
        return tuple(obj)
    else:
        return (obj,)

def hash_obj(obj: object) -> int:
    """Determines a hash, even of potentially mutable objects."""
    if isinstance(obj, dict):
        return hash(tuple(sorted(((hash_obj(k), hash_obj(v)) for k, v in obj.items()))))
    if isinstance(obj, set):
        return hash(tuple(sorted((hash_obj(e) for e in obj))))
    if isinstance(obj, (tuple, list)):
        return hash(tuple((hash_obj(e) for e in obj)))
    return hash(obj)

def get_scene_classes_from_module(module: types.ModuleType) -> list[type[Scene]]:
    from ..scene.scene import Scene

    def is_child_scene(obj: Any, module: types.ModuleType) -> bool:
        return inspect.isclass(obj) and issubclass(obj, Scene) and (obj != Scene) and obj.__module__.startswith(module.__name__)
    return [member[1] for member in inspect.getmembers(module, lambda x: is_child_scene(x, module))]

def get_scenes_to_render(scene_classes: list[type[Scene]]) -> list[type[Scene]]:
    if not scene_classes:
        logger.error(NO_SCENE_MESSAGE)
        return []
    if config['write_all']:
        return scene_classes
    result = []
    for scene_name in config['scene_names']:
        found = False
        for scene_class in scene_classes:
            if scene_class.__name__ == scene_name:
                result.append(scene_class)
                found = True
                break
        if not found and scene_name != '':
            logger.error(SCENE_NOT_FOUND_MESSAGE.format(scene_name))
    if result:
        return result
    if len(scene_classes) == 1:
        config['scene_names'] = [scene_classes[0].__name__]
        return [scene_classes[0]]
    return prompt_user_for_choice(scene_classes)

def prompt_user_for_choice(scene_classes: list[type[Scene]]) -> list[type[Scene]]:
    num_to_class = {}
    SceneFileWriter.force_output_as_scene_name = True
    for count, scene_class in enumerate(scene_classes, 1):
        name = scene_class.__name__
        console.print(f'{count}: {name}', style='logging.level.info')
        num_to_class[count] = scene_class
    try:
        user_input = console.input(f'[log.message] {CHOOSE_NUMBER_MESSAGE} [/log.message]')
        scene_classes = [num_to_class[int(num_str)] for num_str in re.split('\\s*,\\s*', user_input.strip())]
        config['scene_names'] = [scene_class.__name__ for scene_class in scene_classes]
        return scene_classes
    except KeyError:
        logger.error(INVALID_NUMBER_MESSAGE)
        sys.exit(2)
    except EOFError:
        sys.exit(1)
    except ValueError:
        logger.error('No scenes were selected. Exiting.')
        sys.exit(1)

