    if width is None:
        width = config['frame_width']
    if height is None:
        height = config['frame_height']
    projection_matrix = np.array([[2 / width, 0, 0, 0], [0, 2 / height, 0, 0], [0, 0, -2 / (far - near), -(far + near) / (far - near)], [0, 0, 0, 1]])
    if format_:
        return matrix_to_shader_input(projection_matrix)
    else:
        return projection_matrix

def perspective_projection_matrix(width: float | None=None, height: float | None=None, near: float=2, far: float=50, format_: bool=True) -> MatrixMN | FlattenedMatrix4x4:
    if width is None:
        width = config['frame_width'] / 6
    if height is None:
        height = config['frame_height'] / 6
    projection_matrix = np.array([[2 * near / width, 0, 0, 0], [0, 2 * near / height, 0, 0], [0, 0, (far + near) / (near - far), 2 * far * near / (near - far)], [0, 0, -1, 0]])
    if format_:
        return matrix_to_shader_input(projection_matrix)
    else:
        return projection_matrix

def view_matrix(translation: Point3D | None=None, x_rotation: float=0, y_rotation: float=0, z_rotation: float=0) -> MatrixMN:
    if translation is None:
        translation = np.array([0, 0, depth / 2 + 1])
    model_matrix = np.matmul(np.matmul(translation_matrix(*translation), rotation_matrix(x=x_rotation, y=y_rotation, z=z_rotation)), scale_matrix())
    return tuple(linalg.inv(model_matrix).T.ravel())

