@contextlib.contextmanager
def testing(self) -> Generator[None, None, None]:
    with np.load(self._file_path) as data:
        self._frames = data['frame_data']
        if len(self._frames.shape) != 4:
            self._frames = np.expand_dims(self._frames, axis=0)
        logger.debug(self._frames.shape)
        self._number_frames = np.ma.size(self._frames, axis=0)
        yield
        assert self._frames_compared == self._number_frames, f'The scene tested contained {self._frames_compared} frames, when there are {self._number_frames} control frames for this test.'

def check_frame(self, frame_number: int, frame: PixelArray) -> None:
    assert frame_number < self._number_frames, f'The tested scene is at frame number {frame_number} when there are {self._number_frames} control frames.'
    try:
        np.testing.assert_allclose(frame, self._frames[frame_number], atol=FRAME_ABSOLUTE_TOLERANCE, err_msg=f'Frame no {frame_number}. You can use --show_diff to visually show the difference.', verbose=False)
        self._frames_compared += 1
    except AssertionError as e:
        number_of_matches = np.isclose(frame, self._frames[frame_number], atol=FRAME_ABSOLUTE_TOLERANCE).sum()
        number_of_mismatches = frame.size - number_of_matches
        if number_of_mismatches / frame.size < FRAME_MISMATCH_RATIO_TOLERANCE:
            self._frames_compared += 1
            warnings.warn(f'Mismatch of {number_of_mismatches} pixel values in frame {frame_number} against control data in {self._file_path}. Below error threshold, continuing...', stacklevel=1)
            return
        if self._show_diff:
            show_diff_helper(frame_number, frame, self._frames[frame_number], self._file_path.name)
        raise e

