    if hasattr(self, 'tip'):
        result.add(self.tip)
    if hasattr(self, 'start_tip'):
        result.add(self.start_tip)
    return result

def get_tip(self) -> VMobject:
    """Returns the TipableVMobject instance's (first) tip,
        otherwise throws an exception.
        """
    tips = self.get_tips()
    if len(tips) == 0:
        raise Exception('tip not found')
    else:
        tip: VMobject = tips[0]
        return tip

def get_first_handle(self) -> Point3D:
    first_handle: Point3D = self.points[1]
    return first_handle

def get_last_handle(self) -> Point3D:
    last_handle: Point3D = self.points[-2]
    return last_handle

def get_end(self) -> Point3D:
    if self.has_tip():
        return self.tip.get_start()
    else:
        return super().get_end()

def get_start(self) -> Point3D:
    if self.has_start_tip():
        return self.start_tip.get_start()
    else:
        return super().get_start()

def get_length(self) -> float:
    start, end = self.get_start_and_end()
    return float(np.linalg.norm(start - end))

def get_arc_center(self, warning: bool=True) -> Point3D:
    """Looks at the normals to the first two
        anchors, and finds their intersection points
        """
    a1, h1, h2, a2 = self.points[:4]
    if np.all(a1 == a2):
        return np.copy(a1)
    t1 = h1 - a1
    t2 = h2 - a2
    n1 = rotate_vector(t1, TAU / 4)
    n2 = rotate_vector(t2, TAU / 4)
    try:
        return line_intersection(line1=(a1, a1 + n1), line2=(a2, a2 + n2))
    except Exception:
        if warning:
            warnings.warn("Can't find Arc center, using ORIGIN instead", stacklevel=1)
        self._failed_to_get_center = True
        return np.array(ORIGIN)

def move_arc_center_to(self, point: Point3DLike) -> Self:
    self.shift(point - self.get_arc_center())
    return self

def __init__(self, start: Point3DLike, end: Point3DLike, angle: float=TAU / 4, radius: float | None=None, **kwargs: Any) -> None:
    if radius is not None:
        self.radius = radius
        if radius < 0:
            sign = -2
            radius *= -1
        else:
            sign = 2
        halfdist = np.linalg.norm(np.array(start) - np.array(end)) / 2
        if radius < halfdist:
            raise ValueError('ArcBetweenPoints called with a radius that is\n                            smaller than half the distance between the points.')
        arc_height = radius - np.sqrt(radius ** 2 - halfdist ** 2)
        angle = np.arccos((radius - arc_height) / radius) * sign
    super().__init__(radius=radius, angle=angle, **kwargs)
    if angle == 0:
        self.set_points_as_corners(np.array([LEFT, RIGHT]))
    self.put_start_and_end_on(start, end)
    if radius is None:
        center = self.get_arc_center(warning=False)
        if not self._failed_to_get_center:
            self.radius = cast(float, np.linalg.norm(np.array(start) - np.array(center)))
        else:
            self.radius = np.inf

def __init__(self, label: str | SingleStringMathTex | Text | Tex, radius: float | None=None, **kwargs: Any) -> None:
    if isinstance(label, str):
        from manim import MathTex
        rendered_label: VMobject = MathTex(label, color=BLACK)
    else:
        rendered_label = label
    if radius is None:
        radius = 0.1 + max(rendered_label.width, rendered_label.height) / 2
    super().__init__(radius=radius, **kwargs)
    rendered_label.move_to(self.get_center())
    self.add(rendered_label)

def __init__(self, start_anchor: Point3DLike, start_handle: Point3DLike, end_handle: Point3DLike, end_anchor: Point3DLike, **kwargs: Any) -> None:
    super().__init__(**kwargs)
    self.add_cubic_bezier_curve(start_anchor, start_handle, end_handle, end_anchor)

def __init__(self, *vertices: Point3DLike, angle: float=PI / 4, radius: float | None=None, arc_config: list[dict] | None=None, **kwargs: Any) -> None:
    n = len(vertices)
    point_pairs = [(vertices[k], vertices[(k + 1) % n]) for k in range(n)]
    if not arc_config:
        if radius:
            all_arc_configs: Iterable[dict] = itertools.repeat({'radius': radius}, len(point_pairs))
        else:
            all_arc_configs = itertools.repeat({'angle': angle}, len(point_pairs))
    elif isinstance(arc_config, dict):
        all_arc_configs = itertools.repeat(arc_config, len(point_pairs))
    else:
        assert len(arc_config) == n
        all_arc_configs = arc_config
    arcs = [ArcBetweenPoints(*pair, **conf) for pair, conf in zip(point_pairs, all_arc_configs)]
    super().__init__(**kwargs)
    self.add(*arcs)
    for arc in arcs:
        self.append_points(arc.points)
    self.arcs = arcs

def _convert_vmobject_to_skia_path(self, vmobject: VMobject) -> SkiaPath:
    """Converts a :class:`~.VMobject` to SkiaPath. This method only works for
        cairo renderer because it treats the points as Cubic beizer curves.

        Parameters
        ----------
        vmobject:
            The :class:`~.VMobject` to convert from.

        Returns
        -------
        SkiaPath
            The converted path.
        """
    path = SkiaPath()
    if not np.all(np.isfinite(vmobject.points)):
        points = np.zeros((1, 3))
    else:
        points = vmobject.points
    if len(points) == 0:
        return path
    if config.renderer == RendererType.OPENGL:
        subpaths = vmobject.get_subpaths_from_points(points)
        for subpath in subpaths:
            quads = vmobject.get_bezier_tuples_from_points(subpath)
            start = subpath[0]
            path.moveTo(*start[:2])
            for _p0, p1, p2 in quads:
                path.quadTo(*p1[:2], *p2[:2])
            if vmobject.consider_points_equals(subpath[0], subpath[-1]):
                path.close()
    elif config.renderer == RendererType.CAIRO:
        subpaths = vmobject.gen_subpaths_from_points_2d(points)
        for subpath in subpaths:
            quads = vmobject.gen_cubic_bezier_tuples_from_points(subpath)
            start = subpath[0]
            path.moveTo(*start[:2])
            for _p0, p1, p2, p3 in quads:
                path.cubicTo(*p1[:2], *p2[:2], *p3[:2])
            if vmobject.consider_points_equals_2d(subpath[0], subpath[-1]):
                path.close()
    return path

def __init__(self, *vmobjects: VMobject, **kwargs: Any) -> None:
    if len(vmobjects) < 2:
        raise ValueError('At least 2 mobjects needed for Union.')
    super().__init__(**kwargs)
    paths = []
    for vmobject in vmobjects:
        paths.append(self._convert_vmobject_to_skia_path(vmobject))
    outpen = SkiaPath()
    union(paths, outpen.getPen())
    self._convert_skia_path_to_vmobject(outpen)

def __init__(self, label: str | Tex | MathTex | Text, label_config: dict[str, Any] | None=None, box_config: dict[str, Any] | None=None, frame_config: dict[str, Any] | None=None, **kwargs: Any) -> None:
    super().__init__(**kwargs)
    default_label_config: dict[str, Any] = {'color': WHITE, 'font_size': DEFAULT_FONT_SIZE}
    default_box_config: dict[str, Any] = {'color': None, 'buff': 0.05, 'fill_opacity': 1, 'stroke_width': 0.5}
    default_frame_config: dict[str, Any] = {'color': WHITE, 'buff': 0.05, 'stroke_width': 0.5}
    label_config = default_label_config | (label_config or {})
    box_config = default_box_config | (box_config or {})
    frame_config = default_frame_config | (frame_config or {})
    self.rendered_label: MathTex | Tex | Text
    if isinstance(label, str):
        self.rendered_label = MathTex(label, **label_config)
    elif isinstance(label, (MathTex, Tex, Text)):
        self.rendered_label = label
    else:
        raise TypeError('Unsupported label type. Must be MathTex, Tex, or Text.')
    self.background_rect = BackgroundRectangle(self.rendered_label, **box_config)
    self.frame = SurroundingRectangle(self.rendered_label, **frame_config)
    self.add(self.background_rect, self.rendered_label, self.frame)

def _account_for_buff(self, buff: float) -> None:
    if buff <= 0:
        return
    length = self.get_length() if self.path_arc == 0 else self.get_arc_length()
    if length < 2 * buff:
        return
    buff_proportion = buff / length
    self.pointwise_become_partial(self, buff_proportion, 1 - buff_proportion)

def _pointify(self, mob_or_point: Mobject | Point3DLike, direction: Vector3DLike | None=None) -> Point3D:
    """Transforms a mobject into its corresponding point. Does nothing if a point is passed.

        ``direction`` determines the location of the point along its bounding box in that direction.

        Parameters
        ----------
        mob_or_point
            The mobject or point.
        direction
            The direction.
        """
    if isinstance(mob_or_point, (Mobject, OpenGLMobject)):
        mob = mob_or_point
        if direction is None:
            return mob.get_center()
        else:
            return mob.get_boundary_point(direction)
    return np.array(mob_or_point)

def set_path_arc(self, new_value: float) -> None:
    self.path_arc = new_value
    self.init_points()

def set_angle(self, angle: float, about_point: Point3DLike | None=None) -> Self:
    if about_point is None:
        about_point = self.get_start()
    self.rotate(angle - self.get_angle(), about_point=about_point)
    return self

def set_length(self, length: float) -> Self:
    scale_factor: float = length / self.get_length()
    return self.scale(scale_factor)

def get_start(self) -> Point3D:
    """Returns the start point of the line.

        Examples
        --------
        ::

            >>> DashedLine().get_start()
            array([-1.,  0.,  0.])
        """
    if len(self.submobjects) > 0:
        return self.submobjects[0].get_start()
    else:
        return super().get_start()

def get_end(self) -> Point3D:
    """Returns the end point of the line.

        Examples
        --------
        ::

            >>> DashedLine().get_end()
            array([1., 0., 0.])
        """
    if len(self.submobjects) > 0:
        return self.submobjects[-1].get_end()
    else:
        return super().get_end()

def _set_stroke_width_from_length(self) -> Self:
    """Sets stroke width based on length."""
    max_ratio = self.max_stroke_width_to_length_ratio
    if config.renderer == RendererType.OPENGL:
        self.set_stroke(width=min(self.initial_stroke_width, max_ratio * self.get_length()), recurse=False)
    else:
        self.set_stroke(width=min(self.initial_stroke_width, max_ratio * self.get_length()), family=False)
    return self

def __init__(self, direction: Vector2DLike | Vector3DLike=RIGHT, buff: float=0, **kwargs: Any) -> None:
    self.buff = buff
    if len(direction) == 2:
        direction = np.hstack([direction, 0])
    super().__init__(ORIGIN, direction, buff=buff, **kwargs)

def __init__(self, *args: Any, **kwargs: Any) -> None:
    if 'tip_shape_end' in kwargs:
        kwargs['tip_shape'] = kwargs.pop('tip_shape_end')
    tip_shape_start = kwargs.pop('tip_shape_start', ArrowTriangleFilledTip)
    super().__init__(*args, **kwargs)
    self.add_tip(at_start=True, tip_shape=tip_shape_start)

def __init__(self, line1: Line, line2: Line, radius: float | None=None, quadrant: AngleQuadrant=(1, 1), other_angle: bool=False, dot: bool=False, dot_radius: float | None=None, dot_distance: float=0.55, dot_color: ParsableManimColor=WHITE, elbow: bool=False, **kwargs: Any) -> None:
    super().__init__(**kwargs)
    self.lines = (line1, line2)
    self.quadrant = quadrant
    self.dot_distance = dot_distance
    self.elbow = elbow
    inter = line_intersection([line1.get_start(), line1.get_end()], [line2.get_start(), line2.get_end()])
    if radius is None:
        if quadrant[0] == 1:
            dist_1 = np.linalg.norm(line1.get_end() - inter)
        else:
            dist_1 = np.linalg.norm(line1.get_start() - inter)
        if quadrant[1] == 1:
            dist_2 = np.linalg.norm(line2.get_end() - inter)
        else:
            dist_2 = np.linalg.norm(line2.get_start() - inter)
        if np.minimum(dist_1, dist_2) < 0.6:
            radius = 2 / 3 * np.minimum(dist_1, dist_2)
        else:
            radius = 0.4
    else:
        self.radius = radius
    anchor_angle_1 = inter + quadrant[0] * radius * line1.get_unit_vector()
    anchor_angle_2 = inter + quadrant[1] * radius * line2.get_unit_vector()
    if elbow:
        anchor_middle = inter + quadrant[0] * radius * line1.get_unit_vector() + quadrant[1] * radius * line2.get_unit_vector()
        angle_mobject: VMobject = Elbow(**kwargs)
        angle_mobject.set_points_as_corners(np.array([anchor_angle_1, anchor_middle, anchor_angle_2]))
    else:
        angle_1 = angle_of_vector(anchor_angle_1 - inter)
        angle_2 = angle_of_vector(anchor_angle_2 - inter)
        if not other_angle:
            start_angle = angle_1
            if angle_2 > angle_1:
                angle_fin = angle_2 - angle_1
            else:
                angle_fin = 2 * np.pi - (angle_1 - angle_2)
        else:
            start_angle = angle_1
            if angle_2 < angle_1:
                angle_fin = -angle_1 + angle_2
            else:
                angle_fin = -2 * np.pi + (angle_2 - angle_1)
        self.angle_value = angle_fin
        angle_mobject = Arc(radius=radius, angle=self.angle_value, start_angle=start_angle, arc_center=inter, **kwargs)
        if dot:
            if dot_radius is None:
                dot_radius = radius / 10
            else:
                self.dot_radius = dot_radius
            right_dot = Dot(ORIGIN, radius=dot_radius, color=dot_color)
            dot_anchor = inter + (angle_mobject.get_center() - inter) / np.linalg.norm(angle_mobject.get_center() - inter) * radius * dot_distance
            right_dot.move_to(dot_anchor)
            self.add(right_dot)
    self.set_points(angle_mobject.points)

@property
def side_length(self) -> float:
    return float(np.linalg.norm(self.get_vertices()[0] - self.get_vertices()[1]))

@side_length.setter
def side_length(self, value: float) -> None:
    self.scale(value / self.side_length)

def __init__(self, main_shape: VMobject, *mobjects: VMobject, **kwargs: Any) -> None:
    super().__init__(**kwargs)
    self.append_points(main_shape.points)
    sub_direction: Literal['CCW', 'CW'] = 'CCW' if main_shape.get_direction() == 'CW' else 'CW'
    for mobject in mobjects:
        self.append_points(mobject.force_direction(sub_direction).points)

def __init__(self, *mobjects: Mobject, color: ParsableManimColor=YELLOW, buff: float | tuple[float, float]=SMALL_BUFF, corner_radius: float=0.0, **kwargs: Any) -> None:
    from manim.mobject.mobject import Group
    if not all((isinstance(mob, (Mobject, OpenGLMobject)) for mob in mobjects)):
        raise TypeError('Expected all inputs for parameter mobjects to be a Mobjects')
    if isinstance(buff, tuple):
        buff_x = buff[0]
        buff_y = buff[1]
    else:
        buff_x = buff_y = buff
    group = Group(*mobjects)
    super().__init__(color=color, width=group.width + 2 * buff_x, height=group.height + 2 * buff_y, corner_radius=corner_radius, **kwargs)
    self.buff = buff
    self.move_to(group)

def __init__(self, *mobjects: Mobject, color: ParsableManimColor | None=None, stroke_width: float=0, stroke_opacity: float=0, fill_opacity: float=0.75, buff: float | tuple[float, float]=0, **kwargs: Any) -> None:
    if color is None:
        color = config.background_color
    super().__init__(*mobjects, color=color, stroke_width=stroke_width, stroke_opacity=stroke_opacity, fill_opacity=fill_opacity, buff=buff, **kwargs)
    self.original_fill_opacity: float = self.fill_opacity

def pointwise_become_partial(self, mobject: Mobject, a: Any, b: float) -> Self:
    self.set_fill(opacity=b * self.original_fill_opacity)
