def _origin_shift(axis_range: Sequence[float]) -> float:
    ...

def __init__(self, x_range: Sequence[float] | None=None, y_range: Sequence[float] | None=None, x_length: float | None=round(config.frame_width) - 2, y_length: float | None=round(config.frame_height) - 2, axis_config: dict | None=None, x_axis_config: dict | None=None, y_axis_config: dict | None=None, tips: bool=True, **kwargs: Any):
    VGroup.__init__(self, **kwargs)
    CoordinateSystem.__init__(self, x_range, y_range, x_length, y_length)
    self.axis_config = {'include_tip': tips, 'numbers_to_exclude': [0]}
    self.x_axis_config: dict[str, Any] = {}
    self.y_axis_config: dict[str, Any] = {'rotation': 90 * DEGREES, 'label_direction': LEFT}
    self._update_default_configs((self.axis_config, self.x_axis_config, self.y_axis_config), (axis_config, x_axis_config, y_axis_config))
    self.x_axis_config = merge_dicts_recursively(self.axis_config, self.x_axis_config)
    self.y_axis_config = merge_dicts_recursively(self.axis_config, self.y_axis_config)
    if self.x_axis_config.get('scaling') is None or isinstance(self.x_axis_config.get('scaling'), LinearBase):
        self.x_axis_config['exclude_origin_tick'] = True
    else:
        self.x_axis_config['exclude_origin_tick'] = False
    if self.y_axis_config.get('scaling') is None or isinstance(self.y_axis_config.get('scaling'), LinearBase):
        self.y_axis_config['exclude_origin_tick'] = True
    else:
        self.y_axis_config['exclude_origin_tick'] = False
    self.x_axis = self._create_axis(self.x_range, self.x_axis_config, self.x_length)
    self.y_axis = self._create_axis(self.y_range, self.y_axis_config, self.y_length)
    self.axes = VGroup(self.x_axis, self.y_axis)
    self.add(*self.axes)
    lines_center_point = [axis.scaling.function((axis.x_range[1] + axis.x_range[0]) / 2) for axis in self.axes]
    self.shift(-self.coords_to_point(*lines_center_point))

@staticmethod
def _origin_shift(axis_range: Sequence[float]) -> float:
    """Determines how to shift graph mobjects to compensate when 0 is not on the axis.

        Parameters
        ----------
        axis_range
            The range of the axis : ``(x_min, x_max, x_step)``.
        """
    if axis_range[0] > 0:
        return axis_range[0]
    if axis_range[1] < 0:
        return axis_range[1]
    else:
        return 0

def _add_3d_pieces(self) -> None:
    for axis in self.axes:
        axis.pieces = VGroup(*axis.get_pieces(self.num_axis_pieces))
        axis.add(axis.pieces)
        axis.set_stroke(width=0, family=False)
        axis.set_shade_in_3d(True)

def _set_axis_shading(self) -> None:

    def make_func(axis):
        vect = self.light_source
        return lambda: (axis.get_edge_center(-vect), axis.get_edge_center(vect))
    for axis in self:
        for submob in axis.family_members_with_points():
            submob.get_gradient_start_and_end_points = make_func(axis)
            submob.get_unit_normal = lambda a: np.ones(3)
            submob.set_sheen(0.2)

def __init__(self, x_range: Sequence[float] | None=(-config['frame_x_radius'], config['frame_x_radius'], 1), y_range: Sequence[float] | None=(-config['frame_y_radius'], config['frame_y_radius'], 1), x_length: float | None=None, y_length: float | None=None, background_line_style: dict[str, Any] | None=None, faded_line_style: dict[str, Any] | None=None, faded_line_ratio: int=1, make_smooth_after_applying_functions: bool=True, **kwargs: dict[str, Any]):
    self.axis_config: dict[str, Any] = {'stroke_width': 2, 'include_ticks': False, 'include_tip': False, 'line_to_number_buff': SMALL_BUFF, 'label_direction': DR, 'font_size': 24}
    self.y_axis_config: dict[str, Any] = {'label_direction': DR}
    self.background_line_style: dict[str, Any] = {'stroke_color': BLUE_D, 'stroke_width': 2, 'stroke_opacity': 1}
    self._update_default_configs((self.axis_config, self.y_axis_config, self.background_line_style), (kwargs.pop('axis_config', None), kwargs.pop('y_axis_config', None), background_line_style))
    self.faded_line_style = faded_line_style
    self.faded_line_ratio = faded_line_ratio
    self.make_smooth_after_applying_functions = make_smooth_after_applying_functions
    super().__init__(x_range=x_range, y_range=y_range, x_length=x_length, y_length=y_length, axis_config=self.axis_config, y_axis_config=self.y_axis_config, **kwargs)
    self._init_background_lines()

def _init_background_lines(self) -> None:
    """Will init all the lines of NumberPlanes (faded or not)"""
    if self.faded_line_style is None:
        style = dict(self.background_line_style)
        for key in style:
            if isinstance(style[key], numbers.Number):
                style[key] *= 0.5
        self.faded_line_style = style
    self.background_lines, self.faded_lines = self._get_lines()
    self.background_lines.set_style(**self.background_line_style)
