def get_radian_label(self, number: float, font_size: float=24, **kwargs: Any) -> MathTex:
    constant_label = {'PI radians': '\\pi', 'TAU radians': '\\tau'}[self.azimuth_units]
    division = number * {'PI radians': 2, 'TAU radians': 1}[self.azimuth_units]
    frac = fr.Fraction(division).limit_denominator(max_denominator=100)
    if frac.numerator == 0 & frac.denominator == 0:
        string = '0'
    elif frac.numerator == 1 and frac.denominator == 1:
        string = constant_label
    elif frac.numerator == 1:
        if self.azimuth_compact_fraction:
            string = '\\tfrac{' + constant_label + '}{' + str(frac.denominator) + '}'
        else:
            string = '\\tfrac{1}{' + str(frac.denominator) + '}' + constant_label
    elif frac.denominator == 1:
        string = str(frac.numerator) + constant_label
    elif self.azimuth_compact_fraction:
        string = '\\tfrac{' + str(frac.numerator) + constant_label + '}{' + str(frac.denominator) + '}'
    else:
        string = '\\tfrac{' + str(frac.numerator) + '}{' + str(frac.denominator) + '}' + constant_label
    return MathTex(string, font_size=font_size, **kwargs)

