def generate_points(self) -> Self:
    if self.discontinuities is not None:
        discontinuities = filter(lambda t: self.t_min <= t <= self.t_max, self.discontinuities)
        discontinuities_array = np.array(list(discontinuities))
        boundary_times = np.array([self.t_min, self.t_max, *discontinuities_array - self.dt, *discontinuities_array + self.dt])
        boundary_times.sort()
    else:
        boundary_times = [self.t_min, self.t_max]
    for t1, t2 in zip(boundary_times[0::2], boundary_times[1::2]):
        t_range = np.array([*self.scaling.function(np.arange(t1, t2, self.t_step)), self.scaling.function(t2)])
        if self.use_vectorized:
            x, y, z = self.function(t_range)
            if not isinstance(z, np.ndarray):
                z = np.zeros_like(x)
            points = np.stack([x, y, z], axis=1)
        else:
            points = np.array([self.function(t) for t in t_range])
        self.start_new_path(points[0])
        self.add_points_as_corners(points[1:])
    if self.use_smoothing:
        self.make_smooth()
    return self

def generate_points(self) -> Self:
    p_min, p_max = (np.array([self.x_range[0], self.y_range[0]]), np.array([self.x_range[1], self.y_range[1]]))
    curves = plot_isoline(fn=lambda u: self.function(u[0], u[1]), pmin=p_min, pmax=p_max, min_depth=self.min_depth, max_quads=self.max_quads)
    curves = [np.pad(curve, [(0, 0), (0, 1)]) for curve in curves if curve != []]
    for curve in curves:
        self.start_new_path(curve[0])
        self.add_points_as_corners(curve[1:])
    if self.use_smoothing:
        self.make_smooth()
    return self

