def get_subdivision_braces_and_labels(self, parts: VGroup, labels: list[str | VMobject | OpenGLVMobject], direction: Vector3D, buff: float=SMALL_BUFF, min_num_quads: int=1) -> VGroup:
    label_mobs = VGroup()
    braces = VGroup()
    for label, part in zip(labels, parts):
        brace = Brace(part, direction, min_num_quads=min_num_quads, buff=buff)
        if isinstance(label, (VMobject, OpenGLVMobject)):
            label_mob = label
        else:
            label_mob = MathTex(label)
            label_mob.scale(self.default_label_scale_val)
        label_mob.next_to(brace, direction, buff)
        braces.add(brace)
        assert isinstance(label_mob, VMobject)
        label_mobs.add(label_mob)
    parts.braces = braces
    parts.labels = label_mobs
    parts.label_kwargs = {'labels': label_mobs.copy(), 'direction': direction, 'buff': buff}
    return VGroup(parts.braces, parts.labels)

