    if buff == 0:
        return self
    length = self.get_length() if self.path_arc == 0 else self.get_arc_length()
    if length < 2 * buff:
        return self
    buff_prop = buff / length
    self.pointwise_become_partial(self, buff_prop, 1 - buff_prop)
    return self

