    if isinstance(mob_or_point, Mobject):
        mob = mob_or_point
        if direction is None:
            return mob.get_center()
        else:
            return mob.get_continuous_bounding_box_point(direction)
    else:
        point = mob_or_point
        result = np.zeros(self.dim)
        result[:len(point)] = point
        return result

