def __call__(self, **kwargs: Any) -> Self:
    if self.cannot_pass_args:
        raise ValueError('Animation arguments must be passed before accessing methods and can only be passed once')
    self.anim_args = kwargs
    self.cannot_pass_args = True
    return self

def __getattr__(self, method_name: str) -> Callable[..., Self]:
    method = getattr(self.mobject.target, method_name)
    has_overridden_animation = hasattr(method, '_override_animate')
    if self.is_chaining and has_overridden_animation or self.overridden_animation:
        raise NotImplementedError('Method chaining is currently not supported for overridden animations')

    def update_target(*method_args: object, **method_kwargs: object) -> Self:
        if has_overridden_animation:
            self.overridden_animation = cast('Callable[..., Animation]', method._override_animate)(self.mobject, *method_args, anim_args=self.anim_args, **method_kwargs)
        else:
            self.methods.append(MethodWithArgs(method, method_args, method_kwargs))
            method(*method_args, **method_kwargs)
        return self
    self.is_chaining = True
    self.cannot_pass_args = True
    return update_target

def build(self) -> 'Animation':
    from manim.animation.transform import _MethodAnimation
    anim = self.overridden_animation or _MethodAnimation(self.mobject, self.methods)
    for attr, value in self.anim_args.items():
        setattr(anim, attr, value)
    return anim

def add_points(self, points: Point3DLike_Array, rgbas: FloatRGBALike_Array | None=None, color: ParsableManimColor | None=None, opacity: float | None=None) -> Self:
    """Add points.

        Points must be a Nx3 numpy array.
        Rgbas must be a Nx4 numpy array if it is not None.
        """
    if rgbas is None and color is None:
        color = YELLOW
    self.append_points(points)
    if color is not None:
        if opacity is None:
            opacity = self.rgbas[-1, 3]
        new_rgbas = np.repeat([color_to_rgba(color, opacity)], len(points), axis=0)
    elif rgbas is not None:
        new_rgbas = rgbas
    elif len(rgbas) != len(points):
        raise ValueError('points and rgbas must have same length')
    self.rgbas = np.append(self.rgbas, new_rgbas, axis=0)
    return self

def thin_out(self, factor=5):
    """Removes all but every nth point for n = factor"""
    for mob in self.family_members_with_points():
        num_points = mob.get_num_points()

        def thin_func(num_points=num_points):
            return np.arange(0, num_points, factor)
        if len(mob.points) == len(mob.rgbas):
            mob.set_rgba_array_direct(mob.rgbas[thin_func()])
        mob.set_points(mob.points[thin_func()])
    return self

def set_color_by_gradient(self, *colors):
    self.rgbas = np.array(list(map(color_to_rgba, color_gradient(*colors, self.get_num_points()))))
    return self

def set_colors_by_radial_gradient(self, center=None, radius=1, inner_color=WHITE, outer_color=BLACK):
    start_rgba, end_rgba = list(map(color_to_rgba, [inner_color, outer_color]))
    if center is None:
        center = self.get_center()
    for mob in self.family_members_with_points():
        distances = np.abs(self.points - center)
        alphas = np.linalg.norm(distances, axis=1) / radius
        mob.rgbas = np.array(np.array([interpolate(start_rgba, end_rgba, alpha) for alpha in alphas]))
    return self

def match_colors(self, pmobject):
    self.rgbas[:] = resize_with_interpolation(pmobject.rgbas, self.get_num_points())
    return self

def fade_to(self, color, alpha, family=True):
    rgbas = interpolate(self.rgbas, color_to_rgba(color), alpha)
    for mob in self.submobjects:
        mob.fade_to(color, alpha, family)
    self.set_rgba_array_direct(rgbas)
    return self

def filter_out(self, condition):
    for mob in self.family_members_with_points():
        to_keep = ~np.apply_along_axis(condition, 1, mob.points)
        for key in mob.data:
            mob.data[key] = mob.data[key][to_keep]
    return self

def sort_points(self, function=lambda p: p[0]):
    """function is any map from R^3 to R"""
    for mob in self.family_members_with_points():
        indices = np.argsort(np.apply_along_axis(function, 1, mob.points))
        for key in mob.data:
            mob.data[key] = mob.data[key][indices]
    return self

def ingest_submobjects(self):
    for key in self.data:
        self.data[key] = np.vstack([sm.data[key] for sm in self.get_family()])
    return self

def point_from_proportion(self, alpha):
    index = alpha * (self.get_num_points() - 1)
    return self.points[int(index)]

def pointwise_become_partial(self, pmobject, a, b):
    lower_index = int(a * pmobject.get_num_points())
    upper_index = int(b * pmobject.get_num_points())
    for key in self.data:
        self.data[key] = pmobject.data[key][lower_index:upper_index]
    return self

