def uv_func(self, u, v):
    if self.passed_uv_func:
        return self.passed_uv_func(u, v)
    return (u, v, 0.0)

def get_surface_points_and_nudged_points(self) -> tuple[Point3D_Array, Point3D_Array, Point3D_Array]:
    points = self.points
    k = len(points) // 3
    return (points[:k], points[k:2 * k], points[2 * k:])

def get_unit_normals(self) -> Vector3D_Array:
    s_points, du_points, dv_points = self.get_surface_points_and_nudged_points()
    normals = np.cross((du_points - s_points) / self.epsilon, (dv_points - s_points) / self.epsilon)
    return normalize_along_axis(normals, 1)

def pointwise_become_partial(self, smobject, a, b, axis=None):
    assert isinstance(smobject, OpenGLSurface)
    if axis is None:
        axis = self.prefered_creation_axis
    if a <= 0 and b >= 1:
        self.match_points(smobject)
        return self
    nu, nv = smobject.resolution
    self.set_points(np.vstack([self.get_partial_points_array(arr.copy(), a, b, (nu, nv, 3), axis=axis) for arr in smobject.get_surface_points_and_nudged_points()]))
    return self

def get_partial_points_array(self, points, a, b, resolution, axis):
    if len(points) == 0:
        return points
    nu, nv = resolution[:2]
    points = points.reshape(resolution)
    max_index = resolution[axis] - 1
    lower_index, lower_residue = integer_interpolate(0, max_index, a)
    upper_index, upper_residue = integer_interpolate(0, max_index, b)
    if axis == 0:
        points[:lower_index] = interpolate(points[lower_index], points[lower_index + 1], lower_residue)
        points[upper_index + 1:] = interpolate(points[upper_index], points[upper_index + 1], upper_residue)
    else:
        shape = (nu, 1, resolution[2])
        points[:, :lower_index] = interpolate(points[:, lower_index], points[:, lower_index + 1], lower_residue).reshape(shape)
        points[:, upper_index + 1:] = interpolate(points[:, upper_index], points[:, upper_index + 1], upper_residue).reshape(shape)
    return points.reshape((nu * nv, *resolution[2:]))

def sort_faces_back_to_front(self, vect=OUT):
    tri_is = self.triangle_indices
    indices = list(range(len(tri_is) // 3))
    points = self.points

    def index_dot(index):
        return np.dot(points[tri_is[3 * index]], vect)
    indices.sort(key=index_dot)
    for k in range(3):
        tri_is[k::3] = tri_is[k::3][indices]
    return self

def __init__(self, uv_surface: OpenGLSurface, image_file: str | Path, dark_image_file: str | Path=None, image_mode: str | Iterable[str]='RGBA', shader_folder: str | Path=None, **kwargs):
    self.uniforms = {}
    if not isinstance(uv_surface, OpenGLSurface):
        raise Exception('uv_surface must be of type OpenGLSurface')
    if isinstance(image_file, np.ndarray):
        image_file = change_to_rgba_array(image_file)
    if isinstance(image_mode, (str, Path)):
        image_mode = [image_mode] * 2
    image_mode_light, image_mode_dark = image_mode
    texture_paths = {'LightTexture': self.get_image_from_file(image_file, image_mode_light), 'DarkTexture': self.get_image_from_file(dark_image_file or image_file, image_mode_dark)}
    if dark_image_file:
