def set_style(self, fill_color=None, fill_opacity=None, fill_rgba=None, stroke_color=None, stroke_opacity=None, stroke_rgba=None, stroke_width=None, gloss=None, shadow=None, recurse=True):
    if fill_rgba is not None:
        self.fill_rgba = resize_with_interpolation(fill_rgba, len(fill_rgba))
    else:
        self.set_fill(color=fill_color, opacity=fill_opacity, recurse=recurse)
    if stroke_rgba is not None:
        self.stroke_rgba = resize_with_interpolation(stroke_rgba, len(fill_rgba))
        self.set_stroke(width=stroke_width)
    else:
        self.set_stroke(color=stroke_color, width=stroke_width, opacity=stroke_opacity, recurse=recurse)
    if gloss is not None:
        self.set_gloss(gloss, recurse=recurse)
