def match_style(self, vmobject, recurse=True):
    vmobject_style = vmobject.get_style()
    if config.renderer == RendererType.OPENGL:
        vmobject_style['stroke_width'] = vmobject_style['stroke_width'][0][0]
        vmobject_style['fill_opacity'] = self.get_fill_opacity()
    self.set_style(**vmobject_style, recurse=False)
    if recurse:
        submobs1, submobs2 = (self.submobjects, vmobject.submobjects)
        if len(submobs1) == 0:
            return self
        elif len(submobs2) == 0:
            submobs2 = [vmobject]
        for sm1, sm2 in zip(*make_even(submobs1, submobs2)):
            sm1.match_style(sm2)
    return self

def set_color(self, color, opacity=None, recurse=True):
    if opacity is not None:
        self.opacity = opacity
    self.set_fill(color, opacity=opacity, recurse=recurse)
    self.set_stroke(color, opacity=opacity, recurse=recurse)
    return self

def get_color(self):
    if not self.has_fill():
        return self.get_stroke_color()
    return self.get_fill_color()

def get_colors(self):
    if self.has_stroke():
        return self.get_stroke_colors()
    return self.get_fill_colors()

def has_stroke(self):
    stroke_widths = self.get_stroke_widths()
    stroke_opacities = self.get_stroke_opacities()
    return stroke_widths is not None and stroke_opacities is not None and any(stroke_widths) and any(stroke_opacities)

def has_fill(self):
    fill_opacities = self.get_fill_opacities()
    return fill_opacities is not None and any(fill_opacities)

def get_opacity(self):
    if self.has_fill():
        return self.get_fill_opacity()
    return self.get_stroke_opacity()

def set_flat_stroke(self, flat_stroke=True, recurse=True):
    for mob in self.get_family(recurse):
        mob.flat_stroke = flat_stroke
    return self

def add_cubic_bezier_curve(self, anchor1: Point3DLike, handle1: Point3DLike, handle2: Point3DLike, anchor2: Point3DLike):
    new_points = get_quadratic_approximation_of_cubic(anchor1, handle1, handle2, anchor2)
    self.append_points(new_points)

def add_cubic_bezier_curve_to(self, handle1, handle2, anchor):
    """Add cubic bezier curve to the path."""
    self.throw_error_if_no_points()
    quadratic_approx = get_quadratic_approximation_of_cubic(self.get_last_point(), handle1, handle2, anchor)
    if self.has_new_path_started():
        self.append_points(quadratic_approx[1:])
    else:
        self.append_points(quadratic_approx)

def add_quadratic_bezier_curve_to(self, handle, anchor):
    self.throw_error_if_no_points()
    if self.has_new_path_started():
        self.append_points([handle, anchor])
    else:
        self.append_points([self.get_last_point(), handle, anchor])

def add_smooth_curve_to(self, point):
    if self.has_new_path_started():
        self.add_line_to(point)
    else:
        self.throw_error_if_no_points()
        new_handle = self.get_reflection_of_last_handle()
        self.add_quadratic_bezier_curve_to(new_handle, point)
    return self

def get_reflection_of_last_handle(self):
    points = self.points
    return 2 * points[-1] - points[-2]

def close_path(self):
    if not self.is_closed():
        self.add_line_to(self.get_subpaths()[-1][0])

def subdivide_sharp_curves(self, angle_threshold=30 * DEGREES, recurse=True):
    vmobs = [vm for vm in self.get_family(recurse) if vm.has_points()]
    for vmob in vmobs:
        new_points = []
        for tup in vmob.get_bezier_tuples():
            angle = angle_between_vectors(tup[1] - tup[0], tup[2] - tup[1])
            if angle > angle_threshold:
                n = int(np.ceil(angle / angle_threshold))
                alphas = np.linspace(0, 1, n + 1)
                new_points.extend([partial_bezier_points(tup, a1, a2) for a1, a2 in zip(alphas, alphas[1:])])
            else:
                new_points.append(tup)
        vmob.set_points(np.vstack(new_points))
    return self

def add_points_as_corners(self, points):
    for point in points:
        self.add_line_to(point)
    return points

def make_jagged(self):
    self.change_anchor_mode('jagged')
    return self

def append_vectorized_mobject(self, vectorized_mobject):
    new_points = list(vectorized_mobject.points)
    if self.has_new_path_started():
        self.resize_data(len(self.points - 1))
    self.append_points(new_points)
    return self

def get_bezier_tuples_from_points(self, points):
    nppc = self.n_points_per_curve
    remainder = len(points) % nppc
    points = points[:len(points) - remainder]
    return points.reshape((-1, nppc, 3))

def get_area_vector(self):
    if not self.has_points():
        return np.zeros(3)
    nppc = self.n_points_per_curve
    points = self.points
    p0 = points[0::nppc]
    p1 = points[nppc - 1::nppc]
    return 0.5 * np.array([sum((p0[:, 1] + p1[:, 1]) * (p1[:, 2] - p0[:, 2])), sum((p0[:, 2] + p1[:, 2]) * (p1[:, 0] - p0[:, 0])), sum((p0[:, 0] + p1[:, 0]) * (p1[:, 1] - p0[:, 1]))])

def get_unit_normal(self, recompute=False):
    if not recompute:
        return self.unit_normal[0]
    if len(self.points) < 3:
        return OUT
    area_vect = self.get_area_vector()
    area = np.linalg.norm(area_vect)
    if area > 0:
        return area_vect / area
    else:
        points = self.points
        return get_unit_normal(points[1] - points[0], points[2] - points[1])

def refresh_unit_normal(self):
    for mob in self.get_family():
        mob.unit_normal[:] = mob.get_unit_normal(recompute=True)
    return self

def align_points(self, vmobject):
    if self.get_num_points() == len(vmobject.points):
        return
    for mob in (self, vmobject):
        if not mob.has_points():
            mob.start_new_path(mob.get_center())
        if mob.has_new_path_started():
            mob.add_line_to(mob.points[0])
    subpaths1 = self.get_subpaths()
    subpaths2 = vmobject.get_subpaths()
    n_subpaths = max(len(subpaths1), len(subpaths2))
    new_subpaths1 = []
    new_subpaths2 = []
    nppc = self.n_points_per_curve

    def get_nth_subpath(path_list, n):
        if n >= len(path_list):
            return [path_list[-1][-1]] * nppc
        path = path_list[n]
        while len(path) > nppc:
            if self.consider_points_equals(path[-nppc:], path[-nppc - 1]):
                path = path[:-nppc]
            else:
                break
        return path
    for n in range(n_subpaths):
        sp1 = np.asarray(get_nth_subpath(subpaths1, n))
        sp2 = np.asarray(get_nth_subpath(subpaths2, n))
        diff1 = max(0, (len(sp2) - len(sp1)) // nppc)
        diff2 = max(0, (len(sp1) - len(sp2)) // nppc)
        sp1 = self.insert_n_curves_to_point_list(diff1, sp1)
        sp2 = self.insert_n_curves_to_point_list(diff2, sp2)
        new_subpaths1.append(sp1)
        new_subpaths2.append(sp2)
    self.set_points(np.vstack(new_subpaths1))
    vmobject.set_points(np.vstack(new_subpaths2))
    return self

def interpolate(self, mobject1, mobject2, alpha, *args, **kwargs):
    super().interpolate(mobject1, mobject2, alpha, *args, **kwargs)
    if config['use_projection_fill_shaders']:
        self.refresh_triangulation()
    elif self.has_fill():
        tri1 = mobject1.get_triangulation()
        tri2 = mobject2.get_triangulation()
        if len(tri1) != len(tri2) or not np.all(tri1 == tri2):
            self.refresh_triangulation()
    return self

def refresh_triangulation(self) -> Self:
    for mob in self.get_family():
        mob.needs_new_triangulation = True
    return self

@triggers_refreshed_triangulation
def set_points(self, points):
    super().set_points(points)
    return self

@triggers_refreshed_triangulation
def set_data(self, data):
    super().set_data(data)
    return self

@triggers_refreshed_triangulation
def apply_function(self, function, make_smooth=False, **kwargs):
    super().apply_function(function, **kwargs)
    if self.make_smooth_after_applying_functions or make_smooth:
        self.make_approximately_smooth()
    return self

@triggers_refreshed_triangulation
def apply_points_function(self, *args, **kwargs):
    super().apply_points_function(*args, **kwargs)
    return self

@triggers_refreshed_triangulation
def flip(self, *args, **kwargs):
    super().flip(*args, **kwargs)
    return self

def refresh_shader_wrapper_id(self):
    for wrapper in [self.fill_shader_wrapper, self.stroke_shader_wrapper]:
        wrapper.refresh_id()
    return self

def get_fill_shader_wrapper(self):
    self.update_fill_shader_wrapper()
    return self.fill_shader_wrapper

def get_stroke_shader_wrapper(self):
    self.update_stroke_shader_wrapper()
    return self.stroke_shader_wrapper

def get_shader_wrapper_list(self):
    fill_shader_wrappers = []
    stroke_shader_wrappers = []
    back_stroke_shader_wrappers = []
    for submob in self.family_members_with_points():
        if submob.has_fill() and (not config['use_projection_fill_shaders']):
            fill_shader_wrappers.append(submob.get_fill_shader_wrapper())
        if submob.has_stroke() and (not config['use_projection_stroke_shaders']):
            ssw = submob.get_stroke_shader_wrapper()
            if submob.draw_stroke_behind_fill:
                back_stroke_shader_wrappers.append(ssw)
            else:
                stroke_shader_wrappers.append(ssw)
    wrapper_lists = [back_stroke_shader_wrappers, fill_shader_wrappers, stroke_shader_wrappers]
    result = []
    for wlist in wrapper_lists:
        if wlist:
            wrapper = wlist[0]
            wrapper.combine_with(*wlist[1:])
            result.append(wrapper)
    return result

def refresh_shader_data(self):
    self.get_fill_shader_data()
    self.get_stroke_shader_data()

def __init__(self, *vmobjects: OpenGLVMobject, **kwargs: Any):
    super().__init__(**kwargs)
    self.add(*vmobjects)

def get_tip(self) -> Point3D:
    """Returns the point at the brace tip."""
    if config['renderer'] == 'opengl':
        return self.points[34]
    return self.points[28]

def get_direction(self) -> Vector3D:
    """Returns the direction from the center to the brace tip."""
    vect = self.get_tip() - self.get_center()
    return vect / np.linalg.norm(vect)

def __init__(self, obj: Mobject, text: str, brace_direction: Vector3DLike=DOWN, label_constructor: type[SingleStringMathTex | Text]=MathTex, font_size: float=DEFAULT_FONT_SIZE, buff: float=0.2, brace_config: dict[str, Any] | None=None, **kwargs: Any):
    self.label_constructor = label_constructor
    super().__init__(**kwargs)
    self.brace_direction = brace_direction
    if brace_config is None:
        brace_config = {}
    self.brace = Brace(obj, brace_direction, buff, **brace_config)
    if isinstance(text, (tuple, list)):
        self.label: VMobject = self.label_constructor(*text, font_size=font_size, **kwargs)
    else:
        self.label = self.label_constructor(str(text), font_size=font_size)
    self.brace.put_at_tip(self.label)
    self.add(self.brace, self.label)

def shift_brace(self, obj: Mobject, **kwargs: Any) -> Self:
    if isinstance(obj, list):
        obj = self.get_group_class()(*obj)
    self.brace = Brace(obj, self.brace_direction, **kwargs)
    self.brace.put_at_tip(self.label)
    return self

def __init__(self, point_1: Point3DLike, point_2: Point3DLike, direction: Vector3DLike=ORIGIN, **kwargs: Any):
    if all(direction == ORIGIN):
        line_vector = np.array(point_2) - np.array(point_1)
        direction = np.array([line_vector[1], -line_vector[0], 0])
    super().__init__(Line(point_1, point_2), direction=direction, **kwargs)

def __init__(self, arc: Arc | None=None, direction: Vector3DLike=RIGHT, **kwargs: Any):
    if arc is None:
        arc = Arc(start_angle=-1, angle=2, radius=1)
    arc_end_angle = arc.start_angle + arc.angle
    line = Line(UP * arc.start_angle, UP * arc_end_angle)
    scale_shift = RIGHT * np.log(arc.radius)
    if arc.radius >= 1:
        line.scale(arc.radius, about_point=ORIGIN)
        super().__init__(line, direction=direction, **kwargs)
        self.scale(1 / arc.radius, about_point=ORIGIN)
    else:
        super().__init__(line, direction=direction, **kwargs)
    if arc.radius >= 0.3:
        self.shift(scale_shift)
    else:
        self.shift(RIGHT * np.log(0.3))
    self.apply_complex_function(np.exp)
    self.shift(arc.get_arc_center())

@property
def hash_seed(self) -> tuple:
    """A unique hash representing the result of the generated
        mobject points.

        Used as keys in the ``SVG_HASH_TO_MOB_MAP`` caching dictionary.
        """
    return (self.__class__.__name__, self.svg_default, self.path_string_config, self.file_name, config.renderer)

def get_file_path(self) -> Path:
    """Search for an existing file based on the specified file name."""
    if self.file_name is None:
        raise ValueError('Must specify file for SVGMobject')
    return get_full_vector_image_path(self.file_name)

def generate_config_style_dict(self) -> dict[str, str]:
    """Generate a dictionary holding the default style information."""
    keys_converting_dict = {'fill': ('color', 'fill_color'), 'fill-opacity': ('opacity', 'fill_opacity'), 'stroke': ('color', 'stroke_color'), 'stroke-opacity': ('opacity', 'stroke_opacity'), 'stroke-width': ('stroke_width',)}
    svg_default_dict = self.svg_default
    result = {}
    for svg_key, style_keys in keys_converting_dict.items():
        for style_key in style_keys:
            if svg_default_dict[style_key] is None:
                continue
            result[svg_key] = str(svg_default_dict[style_key])
    return result

def get_mobjects_from(self, svg: se.SVG) -> list[VMobject]:
    """Convert the elements of the SVG to a list of mobjects.

        Parameters
        ----------
        svg
            The parsed SVG file.
        """
    result: list[VMobject] = []
    for shape in svg.elements():
        if isinstance(shape, se.Group):
            continue
        elif isinstance(shape, se.Path):
            mob: VMobject = self.path_to_mobject(shape)
        elif isinstance(shape, se.SimpleLine):
            mob = self.line_to_mobject(shape)
        elif isinstance(shape, se.Rect):
            mob = self.rect_to_mobject(shape)
        elif isinstance(shape, (se.Circle, se.Ellipse)):
            mob = self.ellipse_to_mobject(shape)
        elif isinstance(shape, se.Polygon):
            mob = self.polygon_to_mobject(shape)
        elif isinstance(shape, se.Polyline):
            mob = self.polyline_to_mobject(shape)
        elif isinstance(shape, se.Text):
            mob = self.text_to_mobject(shape)
        elif isinstance(shape, se.Use) or type(shape) is se.SVGElement:
            continue
        else:
            logger.warning(f'Unsupported element type: {type(shape)}')
            continue
        if mob is None or not mob.has_points():
            continue
        self.apply_style_to_mobject(mob, shape)
        if isinstance(shape, se.Transformable) and shape.apply:
            self.handle_transform(mob, shape.transform)
        result.append(mob)
    return result

@staticmethod
def line_to_mobject(line: se.Line) -> Line:
    """Convert a line element to a vectorized mobject.

        Parameters
        ----------
        line
            The parsed SVG line.
        """
    return Line(start=_convert_point_to_3d(line.x1, line.y1), end=_convert_point_to_3d(line.x2, line.y2))

@staticmethod
def polygon_to_mobject(polygon: se.Polygon) -> Polygon:
    """Convert a polygon element to a vectorized mobject.

        Parameters
        ----------
        polygon
            The parsed SVG polygon.
        """
    points = [_convert_point_to_3d(*point) for point in polygon]
    return Polygon(*points)

def move_into_position(self) -> None:
    """Scale and move the generated mobject into position."""
    if self.should_center:
        self.center()
    if self.svg_height is not None:
        self.set(height=self.svg_height)
    if self.svg_width is not None:
        self.set(width=self.svg_width)

def generate_points(self) -> None:
    self.handle_commands()
    if config.renderer == 'opengl':
        if self.should_subdivide_sharp_curves:
            self.subdivide_sharp_curves()
        if self.should_remove_null_curves:
            self.set_points(self.get_points_without_null_curves())

def handle_commands(self) -> None:
    all_points: list[np.ndarray] = []
    last_move: np.ndarray = None
    curve_start = None
    last_true_move = None

    def move_pen(pt: np.ndarray, *, true_move: bool=False) -> None:
        nonlocal last_move, curve_start, last_true_move
        last_move = pt
        if curve_start is None:
            curve_start = last_move
        if true_move:
            last_true_move = last_move
    if self.n_points_per_curve == 4:

        def add_cubic(start: np.ndarray, cp1: np.ndarray, cp2: np.ndarray, end: np.ndarray) -> None:
            nonlocal all_points
            assert len(all_points) % 4 == 0, len(all_points)
            all_points += [start, cp1, cp2, end]
            move_pen(end)

        def add_quad(start: np.ndarray, cp: np.ndarray, end: np.ndarray) -> None:
            add_cubic(start, (start + cp + cp) / 3, (cp + cp + end) / 3, end)
            move_pen(end)

        def add_line(start: np.ndarray, end: np.ndarray) -> None:
            add_cubic(start, (start + start + end) / 3, (start + end + end) / 3, end)
            move_pen(end)
    else:

        def add_cubic(start: np.ndarray, cp1: np.ndarray, cp2: np.ndarray, end: np.ndarray) -> None:
            nonlocal all_points
            assert len(all_points) % 3 == 0, len(all_points)
            two_quads = get_quadratic_approximation_of_cubic(start, cp1, cp2, end)
            all_points += two_quads[:3].tolist()
            all_points += two_quads[3:].tolist()
            move_pen(end)

        def add_quad(start: np.ndarray, cp: np.ndarray, end: np.ndarray) -> None:
            nonlocal all_points
            assert len(all_points) % 3 == 0, len(all_points)
            all_points += [start, cp, end]
            move_pen(end)

        def add_line(start: np.ndarray, end: np.ndarray) -> None:
            add_quad(start, (start + end) / 2, end)
            move_pen(end)
    for segment in self.path_obj:
        segment_class = segment.__class__
        if segment_class == se.Move:
            move_pen(_convert_point_to_3d(*segment.end), true_move=True)
        elif segment_class == se.Line:
            add_line(last_move, _convert_point_to_3d(*segment.end))
        elif segment_class == se.QuadraticBezier:
            add_quad(last_move, _convert_point_to_3d(*segment.control), _convert_point_to_3d(*segment.end))
        elif segment_class == se.CubicBezier:
            add_cubic(last_move, _convert_point_to_3d(*segment.control1), _convert_point_to_3d(*segment.control2), _convert_point_to_3d(*segment.end))
        elif segment_class == se.Close:
            if abs(np.linalg.norm(last_move - last_true_move)) > 0.0001:
                add_line(last_move, last_true_move)
            curve_start = None
        else:
            raise AssertionError(f'Not implemented: {segment_class}')
    self.points = np.array(all_points, ndmin=2, dtype='float64')
    if len(all_points) == 0:
        self.points = np.reshape(self.points, (0, 3))

def __init__(self, code_file: StrPath | None=None, code_string: str | None=None, language: str | None=None, formatter_style: str='vim', tab_width: int=4, add_line_numbers: bool=True, line_numbers_from: int=1, background: Literal['rectangle', 'window']='rectangle', background_config: dict[str, Any] | None=None, paragraph_config: dict[str, Any] | None=None):
    super().__init__()
    if code_file is not None:
        code_file = Path(code_file)
        code_string = code_file.read_text(encoding='utf-8')
        lexer = guess_lexer_for_filename(code_file.name, code_string)
    elif code_string is not None:
        if language is not None:
            lexer = get_lexer_by_name(language)
        else:
            lexer = guess_lexer(code_string)
    else:
        raise ValueError('Either a code file or a code string must be specified.')
    code_string = code_string.expandtabs(tabsize=tab_width)
    formatter = HtmlFormatter(style=formatter_style, noclasses=True, cssclasses='')
    soup = BeautifulSoup(highlight(code_string, lexer, formatter), features='html.parser')
    self._code_html = soup.find('pre')
    assert isinstance(self._code_html, Tag)
    color_ranges = []
    current_line_color_ranges = []
    current_line_char_index = 0
    for child in self._code_html.children:
        if child.name == 'span':
            try:
                child_style = child['style']
                if isinstance(child_style, str):
                    color = child_style.removeprefix('color: ')
                else:
                    color = None
            except KeyError:
                color = None
            current_line_color_ranges.append((current_line_char_index, current_line_char_index + len(child.text), color))
            current_line_char_index += len(child.text)
        else:
            for char in child.text:
                if char == '\n':
                    color_ranges.append(current_line_color_ranges)
                    current_line_color_ranges = []
                    current_line_char_index = 0
                else:
                    current_line_char_index += 1
    color_ranges.append(current_line_color_ranges)
    code_lines = self._code_html.get_text().removesuffix('\n').split('\n')
    if paragraph_config is None:
        paragraph_config = {}
    base_paragraph_config = self.default_paragraph_config.copy()
    base_paragraph_config.update(paragraph_config)
    from manim.mobject.text.text_mobject import Paragraph
    self.code_lines = Paragraph(*code_lines, **base_paragraph_config)
    for line, color_range in zip(self.code_lines, color_ranges):
        for start, end, color in color_range:
            line[start:end].set_color(color)
    if add_line_numbers:
        base_paragraph_config.update({'alignment': 'right'})
        self.line_numbers = Paragraph(*[str(i) for i in range(line_numbers_from, line_numbers_from + len(self.code_lines))], **base_paragraph_config)
        self.line_numbers.next_to(self.code_lines, direction=LEFT).align_to(self.code_lines, UP)
        self.add(self.line_numbers)
    for line in self.code_lines:
        line.submobjects = [c for c in line if not isinstance(c, Dot)]
    self.add(self.code_lines)
    if background_config is None:
        background_config = {}
    background_config_base = self.default_background_config.copy()
    background_config_base.update(background_config)
    if background == 'rectangle':
        self.background = SurroundingRectangle(self, **background_config_base)
    elif background == 'window':
        buttons = VGroup((Dot(radius=0.1, stroke_width=0, color=button_color) for button_color in ['#ff5f56', '#ffbd2e', '#27c93f'])).arrange(RIGHT, buff=0.1)
        buttons.next_to(self, UP, buff=0.1).align_to(self, LEFT).shift(LEFT * 0.1)
        self.background = SurroundingRectangle(VGroup(self, buttons), **background_config_base)
        buttons.shift(UP * 0.1 + LEFT * 0.1)
        self.background.add(buttons)
    else:
        raise ValueError(f'Unknown background type: {background}')
    self.add_to_back(self.background)

@classmethod
def get_styles_list(cls) -> list[str]:
    """Get the list of all available formatter styles."""
    if cls._styles_list_cache is None:
        cls._styles_list_cache = list(get_all_styles())
    return cls._styles_list_cache

@property
def font_size(self) -> float:
    """The font size of the tex mobject."""
    return_value: float = self.height / self.initial_height * self._font_size
    return return_value

@font_size.setter
def font_size(self, font_val: float) -> None:
    if font_val <= 0:
        raise ValueError('font_size must be greater than 0.')
    elif self.height > 0:
        self.scale(font_val / self.font_size)

def _set_submobjects_from_number(self, number: float) -> None:
    self.number = number
    self.submobjects = []
    num_string = self._get_num_string(number)
    self.add(*map(self._string_to_mob, num_string))
    if self.show_ellipsis:
        self.add(self._string_to_mob('\\dots', SingleStringMathTex, color=self.color))
    self.arrange(buff=self.digit_buff_per_font_unit * self._font_size, aligned_edge=DOWN)
    if self.unit is not None:
        self.unit_sign = self._string_to_mob(self.unit, SingleStringMathTex)
        self.add(self.unit_sign.next_to(self, direction=RIGHT, buff=(self.unit_buff_per_font_unit + self.digit_buff_per_font_unit) * self._font_size, aligned_edge=DOWN))
    self.move_to(ORIGIN)
    for i, c in enumerate(num_string):
        if c == '-' and len(num_string) > i + 1:
            self[i].align_to(self[i + 1], UP)
            self[i].shift(self[i + 1].height * DOWN / 2)
        elif c == ',':
            self[i].shift(self[i].height * DOWN / 2)
    if self.unit and self.unit.startswith('^'):
        self.unit_sign.align_to(self, UP)
    self.initial_height: float = self.height
    if self.include_background_rectangle:
        self.add_background_rectangle()

def _get_num_string(self, number: float | complex) -> str:
    if isinstance(number, complex):
        formatter = self._get_complex_formatter()
    else:
        formatter = self._get_formatter()
    num_string = formatter.format(number)
    rounded_num = np.round(number, self.num_decimal_places)
    if num_string.startswith('-') and rounded_num == 0:
        num_string = '+' + num_string[1:] if self.include_sign else num_string[1:]
    return num_string

def _string_to_mob(self, string: str, mob_class: type[SingleStringMathTex] | None=None, **kwargs: Any) -> VMobject:
    if mob_class is None:
        mob_class = self.mob_class
    if string not in string_to_mob_map:
        string_to_mob_map[string] = mob_class(string, **kwargs)
    mob = string_to_mob_map[string].copy()
    mob.font_size = self._font_size
    return mob

@property
def font_size(self) -> float:
    """The font size of the tex mobject."""
    return self.height / self.initial_height / SCALE_FACTOR_PER_FONT_POINT

@font_size.setter
def font_size(self, font_val: float) -> None:
    if font_val <= 0:
        raise ValueError('font_size must be greater than 0.')
    elif self.height > 0:
        self.scale(font_val / self.font_size)

def _modify_special_strings(self, tex: str) -> str:
    tex = tex.strip()
    should_add_filler = reduce(op.or_, [tex == '\\over', tex == '\\overline', tex == '\\sqrt', tex == '\\sqrt{', tex.endswith('_'), tex.endswith('^'), tex.endswith('dot')])
    if should_add_filler:
        filler = '{\\quad}'
        tex += filler
    if tex == '\\substack':
        tex = '\\quad'
    if tex == '':
        tex = '\\quad'
    if tex.startswith('\\\\'):
        tex = tex.replace('\\\\', '\\quad\\\\')
    num_lefts, num_rights = (len([s for s in tex.split(substr)[1:] if s and s[0] in '(){}[]|.\\']) for substr in ('\\left', '\\right'))
    if num_lefts != num_rights:
        tex = tex.replace('\\left', '\\big')
        tex = tex.replace('\\right', '\\big')
    tex = self._remove_stray_braces(tex)
    for context in ['array']:
        begin_in = '\\begin{%s}' % context in tex
        end_in = '\\end{%s}' % context in tex
        if begin_in ^ end_in:
            tex = ''
    return tex

def _organize_submobjects_left_to_right(self) -> Self:
    self.sort(lambda p: p[0])
    return self

def init_colors(self, propagate_colors: bool=True) -> Self:
    for submobject in self.submobjects:
        if submobject.color != BLACK:
            continue
        submobject.color = self.color
        if config.renderer == RendererType.OPENGL:
            submobject.init_colors()
        elif config.renderer == RendererType.CAIRO:
            submobject.init_colors(propagate_colors=propagate_colors)
    return self

def __init__(self, *tex_strings: str, arg_separator: str=' ', substrings_to_isolate: Iterable[str] | None=None, tex_to_color_map: dict[str, ParsableManimColor] | None=None, tex_environment: str | None='align*', **kwargs: Any):
    self.tex_template = kwargs.pop('tex_template', config['tex_template'])
    self.arg_separator = arg_separator
    self.substrings_to_isolate = [] if substrings_to_isolate is None else substrings_to_isolate
    if tex_to_color_map is None:
        self.tex_to_color_map: dict[str, ParsableManimColor] = {}
    else:
        self.tex_to_color_map = tex_to_color_map
    self.tex_environment = tex_environment
    self.brace_notation_split_occurred = False
    self.tex_strings = self._break_up_tex_strings(tex_strings)
    try:
        super().__init__(self.arg_separator.join(self.tex_strings), tex_environment=self.tex_environment, tex_template=self.tex_template, **kwargs)
        self._break_up_by_substrings()
    except ValueError as compilation_error:
        if self.brace_notation_split_occurred:
            logger.error(dedent("                        A group of double braces, {{ ... }}, was detected in\n                        your string. Manim splits TeX strings at the double\n                        braces, which might have caused the current\n                        compilation error. If you didn't use the double brace\n                        split intentionally, add spaces between the braces to\n                        avoid the automatic splitting: {{ ... }} --> { { ... } }.\n                        "))
        raise compilation_error
    self.set_color_by_tex_to_color_map(self.tex_to_color_map)
    if self.organize_left_to_right:
        self._organize_submobjects_left_to_right()

def _break_up_tex_strings(self, tex_strings: Sequence[str]) -> list[str]:
    pre_split_length = len(tex_strings)
    tex_strings_brace_splitted = [re.split('{{(.*?)}}', str(t)) for t in tex_strings]
    tex_strings_combined = sum(tex_strings_brace_splitted, [])
    if len(tex_strings_combined) > pre_split_length:
        self.brace_notation_split_occurred = True
    patterns = []
    patterns.extend([f'({re.escape(ss)})' for ss in it.chain(self.substrings_to_isolate, self.tex_to_color_map.keys())])
    pattern = '|'.join(patterns)
    if pattern:
        pieces = []
        for s in tex_strings_combined:
            pieces.extend(re.split(pattern, s))
    else:
        pieces = tex_strings_combined
    return [p for p in pieces if p]

def get_parts_by_tex(self, tex: str, substring: bool=True, case_sensitive: bool=True) -> VGroup:

    def test(tex1: str, tex2: str) -> bool:
        if not case_sensitive:
            tex1 = tex1.lower()
            tex2 = tex2.lower()
        if substring:
            return tex1 in tex2
        else:
            return tex1 == tex2
    return VGroup(*(m for m in self.submobjects if test(tex, m.get_tex_string())))

def get_part_by_tex(self, tex: str, **kwargs: Any) -> MathTex | None:
    all_parts = self.get_parts_by_tex(tex, **kwargs)
    return all_parts[0] if all_parts else None

def set_color_by_tex(self, tex: str, color: ParsableManimColor, **kwargs: Any) -> Self:
    parts_to_color = self.get_parts_by_tex(tex, **kwargs)
    for part in parts_to_color:
        part.set_color(color)
    return self

def set_color_by_tex_to_color_map(self, texs_to_color_map: dict[str, ParsableManimColor], **kwargs: Any) -> Self:
    for texs, color in list(texs_to_color_map.items()):
        try:
            texs + ''
            self.set_color_by_tex(texs, ManimColor(color), **kwargs)
        except TypeError:
            for tex in texs:
                self.set_color_by_tex(tex, ManimColor(color), **kwargs)
    return self

def index_of_part(self, part: MathTex) -> int:
    split_self = self.split()
    if part not in split_self:
        raise ValueError('Trying to get index of part not in MathTex')
    return split_self.index(part)

def index_of_part_by_tex(self, tex: str, **kwargs: Any) -> int:
    part = self.get_part_by_tex(tex, **kwargs)
    if part is None:
        return -1
    return self.index_of_part(part)

def fade_all_but(self, index_or_string: int | str, opacity: float=0.5) -> None:
    arg = index_or_string
    if isinstance(arg, str):
        part: VGroup | VMobject | None = self.get_part_by_tex(arg)
        if part is None:
            raise Exception(f"Could not locate part by provided tex string '{arg}'.")
    elif isinstance(arg, int):
        part = self.submobjects[arg]
    else:
        raise TypeError(f'Expected int or string, got {arg}')
    for other_part in self.submobjects:
        if other_part is part:
            other_part.set_fill(opacity=1)
        else:
            other_part.set_fill(opacity=opacity)

def _set_all_lines_to_initial_positions(self) -> Paragraph:
    """Set all lines to their initial positions."""
    self.lines[1] = [None] * len(self.lines[0])
    for line_no in range(len(self.lines[0])):
        self[line_no].move_to(self.get_center() + self.lines_initial_positions[line_no])
    return self

