def __init__(self, *points: Point3D, tolerance: float=1e-05, **kwargs: Any):
    array = np.array(points)
    hull = QuickHull(tolerance)
    hull.build(array)
    vertices = []
    faces = []
    c = 0
    d = {}
    facets = set(hull.facets) - hull.removed
    for facet in facets:
        tmp = set()
        for subfacet in facet.subfacets:
            for point in subfacet.points:
                if point not in d:
                    vertices.append(point.coordinates)
                    d[point] = c
                    c += 1
                tmp.add(point)
        faces.append([d[point] for point in tmp])
    super().__init__(vertex_coords=vertices, faces_list=faces, **kwargs)

