    self.rotate(-self._current_phi, Z_AXIS, about_point=ORIGIN)
    self.rotate(-self._current_theta, Y_AXIS, about_point=ORIGIN)
    self.rotate(theta, Y_AXIS, about_point=ORIGIN)
    self.rotate(phi, Z_AXIS, about_point=ORIGIN)
    self._current_theta = theta
    self._current_phi = phi

def __init__(self, start: np.ndarray=LEFT, end: np.ndarray=RIGHT, thickness: float=0.02, color: ParsableManimColor | None=None, resolution: int | Sequence[int]=24, **kwargs):
    self.thickness = thickness
    self.resolution = (2, resolution) if isinstance(resolution, int) else resolution
    self.set_start_and_end_attrs(start, end, **kwargs)
    if color is not None:
        self.set_color(color)

def pointify(self, mob_or_point: Mobject | Point3DLike, direction: Vector3DLike | None=None) -> Point3D:
    """Gets a point representing the center of the :class:`Mobjects <.Mobject>`.

        Parameters
        ----------
        mob_or_point
            :class:`Mobjects <.Mobject>` or point whose center should be returned.
        direction
            If an edge of a :class:`Mobjects <.Mobject>` should be returned, the direction of the edge.

        Returns
        -------
        :class:`numpy.array`
            Center of the :class:`Mobjects <.Mobject>` or point, or edge if direction is given.
        """
    if isinstance(mob_or_point, (Mobject, OpenGLMobject)):
        mob = mob_or_point
        if direction is None:
            return mob.get_center()
        else:
            return mob.get_boundary_point(direction)
    return np.array(mob_or_point)

def __init__(self, major_radius: float=3, minor_radius: float=1, u_range: Sequence[float]=(0, TAU), v_range: Sequence[float]=(0, TAU), resolution: tuple[int, int] | None=None, **kwargs) -> None:
    if config.renderer == RendererType.OPENGL:
        res_value = (101, 101)
    elif config.renderer == RendererType.CAIRO:
        res_value = (24, 24)
    resolution = resolution if resolution is not None else res_value
    self.R = major_radius
    self.r = minor_radius
    super().__init__(self.func, u_range=u_range, v_range=v_range, resolution=resolution, **kwargs)

def get_pixel_array(self):
    """A simple getter method."""
    return self.pixel_array

def set_color(self, color, alpha=None, family=True):
    rgb = color_to_int_rgb(color)
    self.pixel_array[:, :, :3] = rgb
    if alpha is not None:
        self.pixel_array[:, :, 3] = int(255 * alpha)
    for submob in self.submobjects:
        submob.set_color(color, alpha, family)
    self.color = color
    return self

def __init__(self, camera: MovingCamera, default_display_frame_config: dict[str, Any] | None=None, **kwargs: Any) -> None:
    self.camera = camera
    if default_display_frame_config is None:
        default_display_frame_config = {'stroke_width': 3, 'stroke_color': WHITE, 'buff': 0}
    self.default_display_frame_config = default_display_frame_config
    self.pixel_array = self.camera.pixel_array
    super().__init__(scale_to_resolution=False, **kwargs)

def get_pixel_array(self):
    self.pixel_array = self.camera.pixel_array
    return self.pixel_array

def interpolate_color(self, mobject1, mobject2, alpha) -> None:
    assert mobject1.pixel_array.shape == mobject2.pixel_array.shape, f'Mobject pixel array shapes incompatible for interpolation.\nMobject 1 ({mobject1}) : {mobject1.pixel_array.shape}\nMobject 2 ({mobject2}) : {mobject2.pixel_array.shape}'
    self.pixel_array = interpolate(mobject1.pixel_array, mobject2.pixel_array, alpha).astype(self.pixel_array_dtype)

def __init__(self, stroke_width: int=DEFAULT_STROKE_WIDTH, **kwargs: Any) -> None:
    self.stroke_width = stroke_width
    super().__init__(**kwargs)

def set_stroke_width(self, width: int, family: bool=True) -> Self:
    mobs = self.family_members_with_points() if family else [self]
    for mob in mobs:
        mob.stroke_width = width
    return self

def set_color_by_gradient(self, *colors: ParsableManimColor) -> Self:
    self.rgbas = np.array(list(map(color_to_rgba, color_gradient(*colors, len(self.points)))))
    return self

def set_colors_by_radial_gradient(self, center: Point3DLike | None=None, radius: float=1, inner_color: ParsableManimColor=WHITE, outer_color: ParsableManimColor=BLACK) -> Self:
    start_rgba, end_rgba = list(map(color_to_rgba, [inner_color, outer_color]))
    if center is None:
        center = self.get_center()
    for mob in self.family_members_with_points():
        distances = np.abs(self.points - center)
        alphas = np.linalg.norm(distances, axis=1) / radius
        mob.rgbas = np.array(np.array([interpolate(start_rgba, end_rgba, alpha) for alpha in alphas]))
    return self

def filter_out(self, condition: npt.NDArray) -> Self:
    for mob in self.family_members_with_points():
        to_eliminate = ~np.apply_along_axis(condition, 1, mob.points)
        mob.points = mob.points[to_eliminate]
        mob.rgbas = mob.rgbas[to_eliminate]
    return self

def thin_out(self, factor: int=5) -> Self:
    """Removes all but every nth point for n = factor"""
    for mob in self.family_members_with_points():
        num_points = self.get_num_points()
        mob.apply_over_attr_arrays(lambda arr, n=num_points: arr[np.arange(0, n, factor)])
    return self

def sort_points(self, function: Callable[[npt.NDArray[ManimFloat]], float]=lambda p: p[0]) -> Self:
    """Function is any map from R^3 to R"""
    for mob in self.family_members_with_points():
        indices = np.argsort(np.apply_along_axis(function, 1, mob.points))
        mob.apply_over_attr_arrays(lambda arr, idx=indices: arr[idx])
    return self

def fade_to(self, color: ParsableManimColor, alpha: float, family: bool=True) -> Self:
    self.rgbas = interpolate(self.rgbas, color_to_rgba(color), alpha)
    for mob in self.submobjects:
        mob.fade_to(color, alpha, family)
    return self

def point_from_proportion(self, alpha: float) -> Any:
    index = alpha * (self.get_num_points() - 1)
    return self.points[np.floor(index)]

@staticmethod
def get_mobject_type_class() -> type[PMobject]:
    return PMobject

def align_points_with_larger(self, larger_mobject: Mobject) -> None:
    assert isinstance(larger_mobject, PMobject)
    self.apply_over_attr_arrays(lambda a: stretch_array_to_length(a, larger_mobject.get_num_points()))

def get_point_mobject(self, center: Point3DLike | None=None) -> Point:
    if center is None:
        center = self.get_center()
    return Point(center)

def pointwise_become_partial(self, mobject: Mobject, a: float, b: float) -> None:
    lower_index, upper_index = (int(x * mobject.get_num_points()) for x in (a, b))
    for attr in self.get_array_attrs():
        full_array = getattr(mobject, attr)
        partial_array = full_array[lower_index:upper_index]
        setattr(self, attr, partial_array)

def add_line(self, start: npt.NDArray, end: npt.NDArray, color: ParsableManimColor | None=None) -> None:
    start, end = list(map(np.array, [start, end]))
    length = np.linalg.norm(end - start)
    if length == 0:
        points = np.array([start])
    else:
        epsilon = self.epsilon / length
        points = np.array([interpolate(start, end, t) for t in np.arange(0, 1, epsilon)])
    self.add_points(points, color=color)

def __init__(self, *pmobs: Any, **kwargs: Any) -> None:
    if not all((isinstance(m, (PMobject, OpenGLPMobject)) for m in pmobs)):
        raise ValueError('All submobjects must be of type PMobject or OpenGLPMObject if using the opengl renderer')
    super().__init__(**kwargs)
    self.add(*pmobs)

def fade_to(self, color: ParsableManimColor, alpha: float, family: bool=True) -> Self:
    if family:
        for mob in self.submobjects:
            mob.fade_to(color, alpha, family)
    return self

def init_points(self) -> None:
    self.reset_points()
    self.generate_points()

def __init__(self, location: Point3DLike=ORIGIN, color: ManimColor=BLACK, **kwargs: Any) -> None:
    self.location = location
    super().__init__(color=color, **kwargs)

@property
def n_points_per_curve(self) -> int:
    return self.n_points_per_cubic_curve

@staticmethod
def get_mobject_type_class() -> type[VMobject]:
    return VMobject

def init_colors(self, propagate_colors: bool=True) -> Self:
    self.set_fill(color=self.fill_color, opacity=self.fill_opacity, family=propagate_colors)
    self.set_stroke(color=self.stroke_color, width=self.stroke_width, opacity=self.stroke_opacity, family=propagate_colors)
    self.set_background_stroke(color=self.background_stroke_color, width=self.background_stroke_width, opacity=self.background_stroke_opacity, family=propagate_colors)
    self.set_sheen(factor=self.sheen_factor, direction=self.sheen_direction, family=propagate_colors)
    if not propagate_colors:
        for submobject in self.submobjects:
            submobject.init_colors(propagate_colors=False)
    return self

def update_rgbas_array(self, array_name: str, color: ParsableManimColor | Iterable[ManimColor] | None=None, opacity: float | None=None) -> Self:
    rgbas = self.generate_rgbas_array(color, opacity)
    if not hasattr(self, array_name):
        setattr(self, array_name, rgbas)
        return self
    curr_rgbas = getattr(self, array_name)
    if len(curr_rgbas) < len(rgbas):
        curr_rgbas = stretch_array_to_length(curr_rgbas, len(rgbas))
        setattr(self, array_name, curr_rgbas)
    elif len(rgbas) < len(curr_rgbas):
        rgbas = stretch_array_to_length(rgbas, len(curr_rgbas))
    if color is not None:
        curr_rgbas[:, :3] = rgbas[:, :3]
    if opacity is not None:
        curr_rgbas[:, 3] = rgbas[:, 3]
    return self

def set_stroke(self, color: ParsableManimColor=None, width: float | None=None, opacity: float | None=None, background=False, family: bool=True) -> Self:
    if family:
        for submobject in self.submobjects:
            submobject.set_stroke(color, width, opacity, background, family)
    if background:
        array_name = 'background_stroke_rgbas'
        width_name = 'background_stroke_width'
        opacity_name = 'background_stroke_opacity'
    else:
        array_name = 'stroke_rgbas'
        width_name = 'stroke_width'
        opacity_name = 'stroke_opacity'
    self.update_rgbas_array(array_name, color, opacity)
    if width is not None:
        setattr(self, width_name, width)
    if opacity is not None:
        setattr(self, opacity_name, opacity)
    if color is not None and background:
        if isinstance(color, (list, tuple)):
            self.background_stroke_color = ManimColor.parse(color)
        else:
            self.background_stroke_color = ManimColor(color)
    return self

def match_style(self, vmobject: VMobject, family: bool=True) -> Self:
    self.set_style(**vmobject.get_style(), family=False)
    if family:
        submobs1, submobs2 = (self.submobjects, vmobject.submobjects)
        if len(submobs1) == 0:
            return self
        elif len(submobs2) == 0:
            submobs2 = [vmobject]
        for sm1, sm2 in zip(*make_even(submobs1, submobs2)):
            sm1.match_style(sm2)
    return self

def get_fill_rgbas(self) -> FloatRGBA_Array:
    try:
        return self.fill_rgbas
    except AttributeError:
        return np.zeros((1, 4))

def get_stroke_rgbas(self, background: bool=False) -> FloatRGBA_Array:
    try:
        if background:
            self.background_stroke_rgbas: FloatRGBA_Array
            rgbas = self.background_stroke_rgbas
        else:
            self.stroke_rgbas: FloatRGBA_Array
            rgbas = self.stroke_rgbas
        return rgbas
    except AttributeError:
        return np.zeros((1, 4))

def get_stroke_width(self, background: bool=False) -> float:
    if background:
        self.background_stroke_width: float
        width = self.background_stroke_width
    else:
        width = self.stroke_width
        if isinstance(width, str):
            width = int(width)
    return max(0.0, width)

def get_color(self) -> ManimColor:
    if np.all(self.get_fill_opacities() == 0):
        return self.get_stroke_color()
    return self.get_fill_color()

def get_gradient_start_and_end_points(self) -> tuple[Point3D, Point3D]:
    if self.shade_in_3d:
        return get_3d_vmob_gradient_start_and_end_points(self)
    else:
        direction = self.get_sheen_direction()
        c = self.get_center()
        bases = np.array([self.get_edge_center(vect) - c for vect in [RIGHT, UP, OUT]]).transpose()
        offset = np.dot(bases, direction)
        return (c - offset, c + offset)

def color_using_background_image(self, background_image: Image | str) -> Self:
    self.background_image: Image | str = background_image
    self.set_color(WHITE)
    for submob in self.submobjects:
        submob.color_using_background_image(background_image)
    return self

def match_background_image(self, vmobject: VMobject) -> Self:
    self.color_using_background_image(vmobject.get_background_image())
    return self

def set_shade_in_3d(self, value: bool=True, z_index_as_group: bool=False) -> Self:
    for submob in self.get_family():
        submob.shade_in_3d = value
        if z_index_as_group:
            submob.z_index_group = self
    return self

def set_points(self, points: Point3DLike_Array) -> Self:
    self.points: Point3D_Array = np.array(points)
    return self

def has_new_path_started(self) -> bool:
    nppcc = self.n_points_per_cubic_curve
    return len(self.points) % nppcc == 1

def close_path(self) -> None:
    if not self.is_closed():
        self.add_line_to(self.get_subpaths()[-1][0])

def append_vectorized_mobject(self, vectorized_mobject: VMobject) -> None:
    if self.has_new_path_started():
        self.points = self.points[:-1]
    self.append_points(vectorized_mobject.points)

def align_rgbas(self, vmobject: VMobject) -> Self:
    attrs = ['fill_rgbas', 'stroke_rgbas', 'background_stroke_rgbas']
    for attr in attrs:
        a1 = getattr(self, attr)
        a2 = getattr(vmobject, attr)
        if len(a1) > len(a2):
            new_a2 = stretch_array_to_length(a2, len(a1))
            setattr(vmobject, attr, new_a2)
        elif len(a2) > len(a1):
            new_a1 = stretch_array_to_length(a1, len(a2))
            setattr(self, attr, new_a1)
    return self

def get_point_mobject(self, center: Point3DLike | None=None) -> VectorizedPoint:
    if center is None:
        center = self.get_center()
    point = VectorizedPoint(center)
    point.match_style(self)
    return point

def interpolate_color(self, mobject1: VMobject, mobject2: VMobject, alpha: float) -> None:
    attrs = ['fill_rgbas', 'stroke_rgbas', 'background_stroke_rgbas', 'stroke_width', 'background_stroke_width', 'sheen_direction', 'sheen_factor']
    for attr in attrs:
        setattr(self, attr, interpolate(getattr(mobject1, attr), getattr(mobject2, attr), alpha))
        if alpha == 1.0:
            val = getattr(mobject2, attr)
            if isinstance(val, np.ndarray):
                val = val.copy()
            setattr(self, attr, val)

def __init__(self, *vmobjects: VMobject | Iterable[VMobject], **kwargs: Any) -> None:
    super().__init__(**kwargs)
    self.add(*vmobjects)

def __init__(self, mapping_or_iterable: Mapping[Hashable, VMobject] | Iterable[tuple[Hashable, VMobject]]={}, show_keys: bool=False, **kwargs) -> None:
    super().__init__(**kwargs)
    self.show_keys = show_keys
    self.submob_dict = {}
    self.add(mapping_or_iterable)

@basecls.width.getter
def width(self) -> float:
    return self.artificial_width

@basecls.height.getter
def height(self) -> float:
    return self.artificial_height

def _throw_error_if_no_submobjects(self):
    if len(self.submobjects) == 0:
        caller_name = sys._getframe(1).f_code.co_name
        raise Exception(f'Cannot call CurvesAsSubmobjects. {caller_name} for a CurvesAsSubmobject with no submobjects')

def _get_submobjects_with_points(self):
    submobjs_with_pts = tuple((part for part in self.submobjects if len(part.points) > 0))
    if len(submobjs_with_pts) == 0:
        caller_name = sys._getframe(1).f_code.co_name
        raise Exception(f'Cannot call CurvesAsSubmobjects. {caller_name} for a CurvesAsSubmobject whose submobjects have no points')
    return submobjs_with_pts

def __init__(self, vmobject: VMobject, num_dashes: int=15, dashed_ratio: float=0.5, dash_offset: float=0, color: ManimColor=WHITE, equal_lengths: bool=True, **kwargs) -> None:
    self.dashed_ratio = dashed_ratio
    self.num_dashes = num_dashes
    super().__init__(color=color, **kwargs)
    r = self.dashed_ratio
    n = self.num_dashes
    if n > 0:
        dash_len = r / n
        if vmobject.is_closed():
            void_len = (1 - r) / n
        else:
            void_len = 1 - r if n == 1 else (1 - r) / (n - 1)
        period = dash_len + void_len
        phase_shift = dash_offset % 1 * period
        if vmobject.is_closed():
            pattern_len = 1
        else:
            pattern_len = 1 + void_len
        dash_starts = [(i * period + phase_shift) % pattern_len for i in range(n)]
        dash_ends = [(i * period + dash_len + phase_shift) % pattern_len for i in range(n)]
        if not vmobject.is_closed():
            if dash_ends[-1] > 1 and dash_starts[-1] > 1:
                dash_ends.pop()
                dash_starts.pop()
            elif dash_ends[-1] < dash_len:
                if dash_starts[-1] < 1:
                    dash_starts.append(0)
                    dash_ends.append(dash_ends[-1])
                    dash_ends[-2] = 1
                else:
                    dash_starts[-1] = 0
            elif dash_starts[-1] > 1 - dash_len:
                dash_ends[-1] = 1
        if equal_lengths:
            norms = np.array(0)
            for k in range(vmobject.get_num_curves()):
                norms = np.append(norms, vmobject.get_nth_curve_length_pieces(k))
            length_vals = np.cumsum(norms)
            ref_points = np.linspace(0, 1, length_vals.size)
            curve_length = length_vals[-1]
            self.add(*(vmobject.get_subcurve(np.interp(dash_starts[i] * curve_length, length_vals, ref_points), np.interp(dash_ends[i] * curve_length, length_vals, ref_points)) for i in range(len(dash_starts))))
        else:
            self.add(*(vmobject.get_subcurve(dash_starts[i], dash_ends[i]) for i in range(len(dash_starts))))
    if config.renderer == RendererType.OPENGL:
        self.match_style(vmobject, recurse=False)
    else:
        self.match_style(vmobject, family=False)

