@cloup.group(context_settings=cli_ctx_settings, invoke_without_command=True, no_args_is_help=True, epilog=EPILOG, help='Manages Manim configuration files.')
@cloup.pass_context
def cfg(ctx: cloup.Context) -> None:
    """Responsible for the cfg subcommand."""
    pass

@cfg.command(context_settings=cli_ctx_settings, no_args_is_help=True)
@cloup.option('-l', '--level', type=cloup.Choice(['user', 'cwd'], case_sensitive=False), default='cwd', help='Specify if this config is for user or the working directory.')
@cloup.option('-o', '--open', 'openfile', is_flag=True)
def write(level: str | None=None, openfile: bool=False) -> None:
    config_paths = config_file_paths()
    console.print('[yellow bold]Manim Configuration File Writer[/yellow bold]', justify='center')
    USER_CONFIG_MSG = f'A configuration file at [yellow]{config_paths[1]}[/yellow] has been created with your required changes.\nThis will be used when running the manim command. If you want to override this config,\nyou will have to create a manim.cfg in the local directory, where you want those changes to be overridden.'
    CWD_CONFIG_MSG = f'A configuration file at [yellow]{config_paths[2]}[/yellow] has been created.\nTo save your config please save that file and place it in your current working directory, from where you run the manim command.'
    parser = make_config_parser()
    if not openfile:
        action = 'save this as'
        for category in parser:
            console.print(f'{category}', style='bold green underline')
            default = cast(dict[str, Any], parser[category])
            if category == 'logger':
                console.print(RICH_COLOUR_INSTRUCTIONS)
                default = replace_keys(default)
            for key in default:
                if category == 'logger' and key not in RICH_NON_STYLE_ENTRIES:
                    desc = 'style'
                    style = default[key]
                else:
                    desc = 'value'
                    style = None
                console.print(f'Enter the {desc} for {key} ', style=style, end='')
                if category != 'logger' or key in RICH_NON_STYLE_ENTRIES:
                    defaultval = repr(default[key]) if isinstance(value_from_string(default[key]), str) else default[key]
                    console.print(f'(defaults to {defaultval}) :', end='')
                try:
                    temp = input()
                except EOFError:
                    raise Exception('Not enough values in input.\nYou may have added a new entry to default.cfg, in which case you will have to\nmodify write_cfg_subcmd_input to account for it.') from None
                if temp:
                    while temp and (not _is_expected_datatype(temp, default[key], bool(style))):
                        console.print(f'[red bold]Invalid {desc}. Try again.[/red bold]')
                        console.print(f'Enter the {desc} for {key}:', style=style, end='')
                        temp = input()
                    default[key] = temp.replace('%', '%%')
            default = replace_keys(default) if category == 'logger' else default
            parser[category] = {i: v.replace('%', '%%') for i, v in dict(default).items()}
    else:
        action = 'open'
    if level is None:
        console.print(f'Do you want to {action} the default config for this User?(y/n)[[n]]', style='dim purple', end='')
        action_to_userpath = input()
    else:
        action_to_userpath = ''
    if action_to_userpath.lower() == 'y' or level == 'user':
        cfg_file_path = config_paths[1]
        guarantee_existence(config_paths[1].parents[0])
        console.print(USER_CONFIG_MSG)
    else:
        cfg_file_path = config_paths[2]
        guarantee_existence(config_paths[2].parents[0])
        console.print(CWD_CONFIG_MSG)
    with cfg_file_path.open('w') as fp:
        parser.write(fp)
    if openfile:
        open_file(cfg_file_path)

@cfg.command(context_settings=cli_ctx_settings)
def show() -> None:
    console.print('CONFIG FILES READ', style='bold green underline')
    for path in config_file_paths():
        if path.exists():
            console.print(f'{path}')
    console.print()
    parser = make_config_parser()
    rich_non_style_entries = [a.replace('.', '_') for a in RICH_NON_STYLE_ENTRIES]
    for category in parser:
        console.print(f'{category}', style='bold green underline')
        for entry in parser[category]:
            if category == 'logger' and entry not in rich_non_style_entries:
                console.print(f'{entry} :', end='')
                console.print(f' {parser[category][entry]}', style=parser[category][entry])
            else:
                console.print(f'{entry} : {parser[category][entry]}')
        console.print('\n')

@cfg.command(context_settings=cli_ctx_settings)
@cloup.option('-d', '--directory', default=Path.cwd())
@cloup.pass_context
def export(ctx: cloup.Context, directory: str) -> None:
    directory_path = Path(directory)
    if directory_path.absolute == Path.cwd().absolute:
        console.print('You are reading the config from the same directory you are exporting to.\nThis means that the exported config will overwrite the config for this directory.\nAre you sure you want to continue? (y/n)', style='red bold', end='')
        proceed = input().lower() == 'y'
    else:
        proceed = True
    if proceed:
        if not directory_path.is_dir():
            console.print(f'Creating folder: {directory}.', style='red bold')
            directory_path.mkdir(parents=True)
        ctx.invoke(write)
        from_path = Path.cwd() / 'manim.cfg'
        to_path = directory_path / 'manim.cfg'
        console.print(f'Exported final Config at {from_path} to {to_path}.')
    else:
